"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import React from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  random,
  useVideoConfig,
} from "remotion";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

// ---------------------------------------------------------------------------
// ascii-dissolve — the frame becomes plain text. The outgoing scene fades as
// a fullscreen field of monospace glyphs rises over it: a deterministic
// noise field drives each cell through a density ramp (" .:-=+*#%@"), so the
// cover reads as living ASCII. It holds fully opaque long enough to be READ
// as text, then the cells drop back down the ramp to space while the
// incoming scene resolves beneath.
//
// Text mode (enterText): the outgoing scene blurs out under the rising
// field; the incoming headline is never previewed as ascii — the field
// dissolves cell by cell (per-cell staggered, never a flat plane) while
// the real text fades in over it. `enterStyle` picks what happens AROUND
// the arriving text:
//   "fade"      — plain: staggered dissolve everywhere, text fades in.
//   "clearing"  — the dissolve order is biased by distance to the text:
//                 cells near the headline vanish first, the field opens a
//                 granular cavity around it.
//   "halo"      — a smooth radial attenuation grows around the text: near
//                 cells slide down the ramp into thin glyphs, a soft dark
//                 well forms behind the headline.
//   "wave"      — one density impulse rides outward from the text: cells
//                 on the wavefront jump up the ramp for a beat, then the
//                 front leaves cleared field behind it.
//   "focus"     — the field defocuses: it blurs and dims while the sharp
//                 text resolves — a depth-of-field handoff.
//   "lime-echo" — on landing, a sparse ring of accent-colored glyphs
//                 flashes once around the headline and settles.
//
// Fully deterministic: per-cell jitter comes from remotion's seeded random,
// the flow from fixed sinusoids over progress, the letterform masks from a
// one-time offscreen-canvas sample of the loaded fonts.
// ---------------------------------------------------------------------------

export type AsciiTextSpec = {
  /** The incoming headline (used for timing and the zone styles). */
  text: string;
  /** Must match the scene's rendered text exactly. */
  fontSize: number;
  /** Concrete family list for canvas sampling (CSS vars won't resolve). */
  fontFamily: string;
  /** Default 400. */
  fontWeight?: number;
  /** Letter-spacing in em, if the scene's text carries one. Default 0. */
  letterSpacingEm?: number;
  /** Glyph color of the ASCII letterform. Default ink. */
  color?: string;
  /** Vertical offset from frame center, px. Default 0. */
  offsetY?: number;
};

export type AsciiEnterStyle =
  | "fade"
  | "clearing"
  | "halo"
  | "wave"
  | "focus"
  | "lime-echo";

export type AsciiDissolveProps = {
  /** Row height of one glyph cell in px. Default 22 (use ~14 in text mode). */
  cellSize?: number;
  /** Glyph color. Default translucent ink. */
  colorFront?: string;
  /** Canvas behind the glyphs during the hold. Default near-black. */
  colorBack?: string;
  /** Optional second color for a sparse scattering of accent cells. */
  accentColor?: string;
  /** Share of cells rendered in the accent color, 0..1. Default 0.05. */
  accentDensity?: number;
  /** Density ramp, lightest → densest. Default " .:-=+*#%@". */
  ramp?: string;
  /** Monospace stack for the field. */
  fontFamily?: string;
  /** Text mode: the incoming headline (used for timing and as the zone). */
  enterText?: AsciiTextSpec;
  /** What happens around the arriving text. Default "fade". */
  enterStyle?: AsciiEnterStyle;
  /** Progress window over which the outgoing scene fades out. */
  exitFade?: [number, number];
  /** Progress window over which the incoming scene resolves. */
  enterFade?: [number, number];
};

// Per-cell stagger: global window progress g plus jitter j → this cell's
// local progress. spread controls how far cells drift apart.
const stagger = (g: number, j: number, spread = 0.55) =>
  Math.max(0, Math.min(1, (g - j * spread) / (1 - spread)));

// The field's mono advance, measured at the size the <pre> renders.
const measureAdvance = (fontFamily: string, fontSize: number): number => {
  const fallback = fontSize * 0.6;
  if (typeof document === "undefined") return fallback;
  const ctx = document.createElement("canvas").getContext("2d");
  if (!ctx) return fallback;
  ctx.font = `400 ${fontSize}px ${fontFamily}`;
  const w = ctx.measureText("0").width;
  return w > 0 ? w : fallback;
};

// Sample the headline's letterforms: draw the text once on an offscreen
// canvas at 2× cell resolution and grade each cell by subsample coverage
// (0..4). Edge cells get mid-ramp glyphs, core cells the densest — the
// grading anti-aliases the letter contours, so strokes thinner than a cell
// still read as continuous letters.
const buildTextMask = (
  spec: AsciiTextSpec,
  width: number,
  height: number,
  cols: number,
  rows: number,
  advance: number,
  cellH: number,
): Uint8Array | null => {
  if (typeof document === "undefined") return null;
  const canvas = document.createElement("canvas");
  canvas.width = cols * 2;
  canvas.height = rows * 2;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  if (!ctx) return null;
  ctx.setTransform(2 / advance, 0, 0, 2 / cellH, 0, 0);
  ctx.font = `${spec.fontWeight ?? 400} ${spec.fontSize}px ${spec.fontFamily}`;
  const spacing = (spec.letterSpacingEm ?? 0) * spec.fontSize;
  if (spacing !== 0) {
    (
      ctx as CanvasRenderingContext2D & { letterSpacing?: string }
    ).letterSpacing = `${spacing}px`;
  }
  ctx.textAlign = "center";
  // Canvas "middle" baseline is computed from the em square and lands
  // visibly ABOVE where a flex-centered DOM span puts the same text. Rebuild
  // the DOM's math instead: a flex-centered span (line-height normal) puts
  // its baseline at H/2 + (ascent - descent)/2, with ascent/descent taken
  // from the font's own metrics.
  ctx.textBaseline = "alphabetic";
  ctx.fillStyle = "#fff";
  const metrics = ctx.measureText(spec.text);
  const ascent = metrics.fontBoundingBoxAscent ?? spec.fontSize * 0.8;
  const descent = metrics.fontBoundingBoxDescent ?? spec.fontSize * 0.2;
  const baselineY = height / 2 + (ascent - descent) / 2 + (spec.offsetY ?? 0);
  ctx.fillText(spec.text, width / 2, baselineY);
  const data = ctx.getImageData(0, 0, cols * 2, rows * 2).data;
  const mask = new Uint8Array(cols * rows);
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      let hits = 0;
      if (data[(y * 2 * cols * 2 + x * 2) * 4 + 3] > 100) hits++;
      if (data[(y * 2 * cols * 2 + x * 2 + 1) * 4 + 3] > 100) hits++;
      if (data[((y * 2 + 1) * cols * 2 + x * 2) * 4 + 3] > 100) hits++;
      if (data[((y * 2 + 1) * cols * 2 + x * 2 + 1) * 4 + 3] > 100) hits++;
      mask[y * cols + x] = hits;
    }
  }
  return mask;
};

const AsciiDissolvePresentation: React.FC<
  TransitionPresentationComponentProps<AsciiDissolveProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const {
    cellSize = 22,
    colorFront = "rgba(242,242,242,0.6)",
    colorBack = "#0d0d10",
    accentColor,
    accentDensity = 0.05,
    ramp = " .:-=+*#%@",
    fontFamily = "ui-monospace, SFMono-Regular, Menlo, monospace",
    enterText,
    enterStyle = "fade",
    exitFade,
    enterFade,
  } = passedProps;
  const { width, height } = useVideoConfig();
  const entering = presentationDirection === "entering";
  const p = presentationProgress;
  const textMode = enterText !== undefined;

  // The outgoing scene blurs out under the rising field.
  const exitWindow = exitFade ?? [0.14, 0.3];
  // The real text fades in while the field dissolves cell by cell.
  const enterWindow = enterFade ?? (textMode ? [0.6, 0.8] : [0.62, 0.8]);

  // The masks and the mono advance must be measured with the REAL webfonts.
  // The component can mount while they are still loading (a fallback font
  // would bake wrong metrics into the memoized masks and shift the letterform
  // off the scene's text) — so gate on document.fonts and hold the render.
  const [fontsReady, setFontsReady] = React.useState(
    () => typeof document === "undefined" || document.fonts.status === "loaded",
  );
  React.useEffect(() => {
    if (fontsReady || typeof document === "undefined") return;
    const handle = delayRender("ascii-dissolve: waiting for fonts");
    let alive = true;
    document.fonts.ready.then(() => {
      if (alive) setFontsReady(true);
      continueRender(handle);
    });
    return () => {
      alive = false;
      continueRender(handle);
    };
  }, [fontsReady]);

  const fontSize = cellSize * 0.86;
  // biome-ignore lint/correctness/useExhaustiveDependencies: fontsReady is an intentional extra dep — remeasure the mono advance once the real webfonts load
  const advance = React.useMemo(
    () => measureAdvance(fontFamily, fontSize),
    [fontFamily, fontSize, fontsReady],
  );
  const cols = Math.ceil(width / advance);
  const rows = Math.ceil(height / cellSize) + 1;

  // The zone styles need to know where the incoming text sits — a capsule
  // around its center line, derived from the letterform mask's bounds. The
  // mask itself is never displayed.
  const zoneStyles: AsciiEnterStyle[] = [
    "clearing",
    "halo",
    "wave",
    "lime-echo",
  ];
  const needZone = enterText !== undefined && zoneStyles.includes(enterStyle);
  const enterMask = React.useMemo(
    () =>
      enterText && needZone && fontsReady
        ? buildTextMask(enterText, width, height, cols, rows, advance, cellSize)
        : null,
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      enterText,
      needZone,
      fontsReady,
      width,
      height,
      cols,
      rows,
      advance,
      cellSize,
    ],
  );
  const enterZone = React.useMemo(() => {
    if (enterMask === null) return null;
    let minX = Infinity;
    let maxX = -Infinity;
    let minY = Infinity;
    let maxY = -Infinity;
    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        if (enterMask[y * cols + x] > 0) {
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
        }
      }
    }
    if (maxX < minX) return null;
    return {
      x0: minX * advance,
      x1: (maxX + 1) * advance,
      cy: ((minY + maxY + 1) / 2) * cellSize,
      halfH: ((maxY - minY + 1) / 2) * cellSize,
    };
  }, [enterMask, cols, rows, advance, cellSize]);

  if (!entering) {
    const exitStyle: React.CSSProperties = {
      opacity: interpolate(p, exitWindow, [1, 0], clampOpts),
      filter: `blur(${interpolate(p, [exitWindow[0], exitWindow[1] + 0.06], [0, 8], clampOpts)}px)`,
    };
    return <AbsoluteFill style={exitStyle}>{children}</AbsoluteFill>;
  }

  // -------------------------------------------------------------------------
  // Envelopes.
  // -------------------------------------------------------------------------
  // Generic mode keeps the original flat envelopes; text mode staggers the
  // rise and the dissolve per cell instead, so nothing moves as one plane.
  const coverage = textMode
    ? 1
    : interpolate(p, [0.06, 0.28, 0.6, 0.9], [0, 1, 1, 0], clampOpts);
  const fieldOpacity = textMode
    ? 1
    : interpolate(p, [0.04, 0.2, 0.66, 0.94], [0, 1, 1, 0], clampOpts);
  const panelOpacity = textMode
    ? interpolate(p, [0.06, 0.24, 0.55, 0.75], [0, 1, 1, 0], clampOpts)
    : fieldOpacity;

  // Text-mode phase clocks. The outgoing scene blurs out as the field
  // rises; the field boils, then dissolves cell by cell while the real
  // text fades in.
  const riseG = interpolate(p, [0.04, 0.3], [0, 1], clampOpts);
  const dissolveG = interpolate(
    p,
    enterStyle === "clearing" ? [0.52, 0.85] : [0.5, 0.82],
    [0, 1],
    clampOpts,
  );

  // Style clocks for the arriving text's surroundings.
  const haloG = interpolate(p, [0.52, 0.74], [0, 1], clampOpts);
  const waveT = interpolate(p, [0.56, 0.94], [0, 1], {
    ...clampOpts,
    easing: Easing.out(Easing.quad),
  });
  const waveR = waveT * 860; //  the impulse front, px from the text capsule
  const echoFlash = interpolate(p, [0.56, 0.64, 0.82], [0, 0.9, 0], clampOpts);
  const focusBlur = interpolate(p, [0.55, 0.9], [0, 4], clampOpts);
  const focusFade = interpolate(p, [0.62, 0.94], [1, 0], clampOpts);

  const cx = cols / 2;
  const cy = rows / 2;
  const t = p * 5;
  const rampLen = ramp.length;

  const mainRows: string[] = [];
  const accentRows: string[] = [];
  const echoRows: string[] = [];
  const fieldAlive = textMode ? p < 0.999 : fieldOpacity > 0.001;

  if (fieldAlive) {
    for (let y = 0; y < rows; y++) {
      let mainRow = "";
      let accentRow = "";
      let echoRow = "";
      for (let x = 0; x < cols; x++) {
        // A slow sinusoid flow plus per-cell jitter — organic, but textual.
        const base =
          0.5 +
          (Math.sin(x * 0.33 + t * 1.7) +
            Math.sin(y * 0.51 - t * 1.2) +
            Math.sin((x * 0.5 + y) * 0.24 + t * 0.9) +
            Math.sin(Math.hypot(x - cx, (y - cy) * 1.8) * 0.42 - t * 2.1)) /
            8;
        const jitter = random(`ascii-${x}-${y}`);

        // Distance to the incoming text's capsule, for the zone styles —
        // and the plain circular distance from its center, for the wave.
        let dist = Infinity;
        let distC = Infinity;
        let s = 0; // proximity, 1 at the text's center line → 0 far away
        if (enterZone !== null) {
          const px = (x + 0.5) * advance;
          const py = (y + 0.5) * cellSize;
          const nx = Math.min(Math.max(px, enterZone.x0), enterZone.x1);
          dist = Math.hypot(px - nx, py - enterZone.cy);
          distC = Math.hypot(
            px - (enterZone.x0 + enterZone.x1) / 2,
            py - enterZone.cy,
          );
          s = Math.max(0, 1 - dist / (enterZone.halfH + 64));
        }

        let cellCoverage: number;
        if (!textMode) {
          cellCoverage = coverage;
        } else if (enterStyle === "clearing" && enterZone !== null) {
          // Dissolve order biased by proximity: cells near the headline
          // vanish first, a granular cavity opens outward.
          const order = (1 - s) * 0.6 + random(`ascii-d-${x}-${y}`) * 0.4;
          const gone = Math.max(
            0,
            Math.min(1, (dissolveG * 1.35 - order) / 0.3),
          );
          cellCoverage = stagger(riseG, jitter) * (1 - gone);
        } else if (enterStyle === "wave" && enterZone !== null) {
          // The impulse front — a CIRCLE from the text's center — clears
          // the field behind it.
          const passed = Math.max(0, Math.min(1, (waveR - distC) / 55));
          cellCoverage = stagger(riseG, jitter) * (1 - passed);
        } else {
          cellCoverage =
            stagger(riseG, jitter) *
            (1 - stagger(dissolveG, random(`ascii-d-${x}-${y}`)));
        }

        let d = Math.max(
          0,
          Math.min(
            0.999,
            (base * 0.72 + jitter * 0.28) * cellCoverage * 1.2 - 0.08,
          ),
        );
        if (enterStyle === "halo" && enterZone !== null) {
          // A smooth radial attenuation: near cells slide down the ramp.
          d *= 1 - haloG * s;
        }
        if (enterStyle === "wave" && enterZone !== null && waveT > 0) {
          // Cells on the circular wavefront jump up the ramp for a beat.
          const bump = Math.exp(-(((distC - waveR) / 55) ** 2));
          d = Math.min(0.999, d + bump * 0.5);
        }
        const ch = ramp[Math.floor(d * rampLen)] ?? " ";
        const isAccent =
          accentColor !== undefined &&
          random(`ascii-a-${x}-${y}`) < accentDensity;
        mainRow += isAccent ? " " : ch;
        accentRow += isAccent ? ch : " ";

        // The lime echo: a sparse ring of accent glyphs around the headline.
        if (
          enterStyle === "lime-echo" &&
          enterZone !== null &&
          echoFlash > 0.01 &&
          dist > 8 &&
          dist < 84 &&
          ch !== " " &&
          random(`ascii-e-${x}-${y}`) < 0.5
        ) {
          echoRow += ch;
        } else {
          echoRow += " ";
        }
      }
      mainRows.push(mainRow);
      accentRows.push(accentRow);
      echoRows.push(echoRow);
    }
  }

  // The blur must hit exactly 0 by p = 1: the entering presentation stays
  // mounted at p = 1 for the whole scene, so any residue would soften the
  // incoming scene permanently. In text mode the incoming scene resolves
  // with NO transform at all — it must sit pixel-exact under the letterform.
  const enterBlur = textMode
    ? 0
    : interpolate(
        p,
        [enterWindow[0], Math.min(1, enterWindow[1] + 0.05)],
        [10, 0],
        clampOpts,
      );
  const childStyle: React.CSSProperties = textMode
    ? { opacity: interpolate(p, enterWindow, [0, 1], clampOpts) }
    : {
        opacity: interpolate(p, enterWindow, [0, 1], clampOpts),
        scale: `${interpolate(p, [enterWindow[0], 1], [1.04, 1], {
          ...clampOpts,
          easing: Easing.out(Easing.cubic),
        })}`,
        filter: enterBlur > 0.01 ? `blur(${enterBlur}px)` : undefined,
      };

  const preStyle: React.CSSProperties = {
    margin: 0,
    position: "absolute",
    inset: 0,
    overflow: "hidden",
    whiteSpace: "pre",
    fontFamily,
    fontSize,
    lineHeight: `${cellSize}px`,
    color: colorFront,
  };

  const renderLayer = (
    layerRows: string[],
    color: string,
    layerOpacity: number,
  ) =>
    layerOpacity > 0.001 ? (
      <pre style={{ ...preStyle, color, opacity: layerOpacity }}>
        {layerRows.join("\n")}
      </pre>
    ) : null;

  return (
    <AbsoluteFill>
      <AbsoluteFill style={childStyle}>{children}</AbsoluteFill>
      {fieldAlive ? (
        <AbsoluteFill style={{ pointerEvents: "none" }}>
          <AbsoluteFill
            style={{ background: colorBack, opacity: panelOpacity }}
          />
          <AbsoluteFill
            style={
              enterStyle === "focus" && textMode
                ? {
                    opacity: focusFade,
                    filter:
                      focusBlur > 0.01 ? `blur(${focusBlur}px)` : undefined,
                  }
                : undefined
            }
          >
            {renderLayer(mainRows, colorFront, fieldOpacity)}
            {accentColor !== undefined
              ? renderLayer(accentRows, accentColor, fieldOpacity)
              : null}
          </AbsoluteFill>
          {enterStyle === "lime-echo"
            ? renderLayer(echoRows, accentColor ?? "#C3E88D", echoFlash)
            : null}
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

export function asciiDissolve(
  props: AsciiDissolveProps = {},
): TransitionPresentation<AsciiDissolveProps> {
  return {
    component: AsciiDissolvePresentation,
    props,
  };
}

"use client";

import type React from "react";
import { AbsoluteFill, useVideoConfig } from "remotion";
import {
  type CanvasFilterProps,
  makeCanvasFilter,
  makeFilterShader,
} from "@/lib/remocn/canvas-presentation";

export type AsciiRenderProps = {
  glyphSize?: number;
  charset?: string;
  colored?: boolean;
  ink?: string;
  intensity?: number;
};

const DEFAULTS = {
  glyphSize: 26,
  charset: " .:-=+*#%@",
  colored: false,
  ink: "#9dff9d",
  intensity: 1,
};

const GLYPH_ASPECT = 0.545;
const ATLAS_CELL_W = 24;
const ATLAS_CELL_H = 44;
const ATLAS_FONT =
  'ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace';

type NormalizedProps = {
  cellX: number;
  cellY: number;
  charset: string;
  colored: boolean;
  ink: string;
  intensity: number;
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform sampler2D u_atlas;
uniform vec2 u_cell;
uniform float u_glyph_count;
uniform float u_colored;
uniform vec3 u_ink;
uniform float u_intensity;

in vec2 v_uv;
out vec4 outColor;

const int TAPS = 3;

vec4 cellAverage(vec2 center, vec2 cell) {
  vec4 sum = vec4(0.0);
  for (int y = 0; y < TAPS; y++) {
    for (int x = 0; x < TAPS; x++) {
      vec2 offset = (vec2(float(x), float(y)) + 0.5) / float(TAPS) - 0.5;
      sum += texture(u_scene, center + offset * cell);
    }
  }
  return sum / float(TAPS * TAPS);
}

void main() {
  vec2 cell = max(u_cell, vec2(0.001));
  vec2 origin = floor(v_uv / cell) * cell;
  vec4 sampled = cellAverage(origin + cell * 0.5, cell);

  float luma = dot(sampled.rgb, vec3(0.299, 0.587, 0.114));
  float index = min(floor(luma * u_glyph_count), u_glyph_count - 1.0);

  vec2 local = clamp((v_uv - origin) / cell, 0.008, 0.992);
  float mask =
    texture(u_atlas, vec2((index + local.x) / u_glyph_count, local.y)).r;

  vec3 glyph = mix(u_ink, sampled.rgb, u_colored) * mask;
  vec4 source = texture(u_scene, v_uv);
  float amount = clamp(u_intensity, 0.0, 1.0);

  outColor = vec4(
    mix(source.rgb, glyph, amount),
    mix(source.a, max(mask, sampled.a), amount)
  );
}`;

type Atlas = { charset: string; texture: WebGLTexture };

const atlases = new WeakMap<WebGL2RenderingContext, Atlas>();

function drawAtlas(charset: string): OffscreenCanvas {
  const canvas = new OffscreenCanvas(
    ATLAS_CELL_W * charset.length,
    ATLAS_CELL_H,
  );
  const context = canvas.getContext("2d");
  if (!context) {
    throw new Error("ascii-render: failed to acquire a 2D context");
  }
  context.fillStyle = "#000000";
  context.fillRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = "#ffffff";
  context.font = `${Math.round(ATLAS_CELL_H * 0.74)}px ${ATLAS_FONT}`;
  context.textAlign = "center";
  context.textBaseline = "middle";
  for (let i = 0; i < charset.length; i++) {
    context.fillText(
      charset[i],
      i * ATLAS_CELL_W + ATLAS_CELL_W / 2,
      ATLAS_CELL_H / 2,
    );
  }
  return canvas;
}

function bindAtlas(gl: WebGL2RenderingContext, charset: string): void {
  gl.activeTexture(gl.TEXTURE1);

  let atlas = atlases.get(gl);
  if (!atlas) {
    const texture = gl.createTexture();
    if (!texture) {
      throw new Error("ascii-render: failed to create the glyph atlas");
    }
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    atlas = { charset: "", texture };
    atlases.set(gl, atlas);
  } else {
    gl.bindTexture(gl.TEXTURE_2D, atlas.texture);
  }

  if (atlas.charset !== charset) {
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.RGBA,
      gl.RGBA,
      gl.UNSIGNED_BYTE,
      drawAtlas(charset),
    );
    atlas.charset = charset;
  }
}

function toRgb(hex: string): [number, number, number] {
  const value = hex.replace("#", "");
  const full =
    value.length === 3
      ? value
          .split("")
          .map((c) => c + c)
          .join("")
      : value;
  const int = Number.parseInt(full, 16);
  if (Number.isNaN(int)) return [1, 1, 1];
  return [
    ((int >> 16) & 255) / 255,
    ((int >> 8) & 255) / 255,
    (int & 255) / 255,
  ];
}

const shader = makeFilterShader<NormalizedProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const { cellX, cellY, charset, colored, ink, intensity } = passedProps;
    bindAtlas(gl, charset);
    gl.uniform1i(uniform("u_atlas"), 1);
    gl.uniform1f(uniform("u_glyph_count"), charset.length);
    gl.uniform2f(uniform("u_cell"), cellX, cellY);
    gl.uniform1f(uniform("u_colored"), colored ? 1 : 0);
    gl.uniform3fv(uniform("u_ink"), toRgb(ink));
    gl.uniform1f(uniform("u_intensity"), intensity);
  },
);

const AsciiRenderFallback: React.FC<NormalizedProps & CanvasFilterProps> = ({
  children,
}) => <AbsoluteFill>{children}</AbsoluteFill>;

const AsciiRenderCanvas = makeCanvasFilter<NormalizedProps>({
  shader,
  fallback: AsciiRenderFallback,
});

export const AsciiRender: React.FC<AsciiRenderProps & CanvasFilterProps> = ({
  glyphSize = DEFAULTS.glyphSize,
  charset = DEFAULTS.charset,
  colored = DEFAULTS.colored,
  ink = DEFAULTS.ink,
  intensity = DEFAULTS.intensity,
  children,
}) => {
  const { width, height } = useVideoConfig();
  const resolved = charset.length > 0 ? charset : DEFAULTS.charset;

  return (
    <AsciiRenderCanvas
      cellX={(glyphSize * GLYPH_ASPECT) / width}
      cellY={glyphSize / height}
      charset={resolved}
      colored={colored}
      ink={ink}
      intensity={intensity}
    >
      {children}
    </AsciiRenderCanvas>
  );
};

"use client";

import { hash01 } from "@/lib/remocn/stop-motion";

const GRAIN_RATIO = 0.5;
const GRAIN_FREQUENCY = 0.7;
const GRAIN_OCTAVES = 3;

export type BrushPoint = { x: number; y: number };

export type BrushTaper = {
  strokeWidth: number;
  pressure?: number;
  release?: number;
};

export function brushHalfWidth(taper: BrushTaper, t: number): number {
  const pressure = taper.pressure ?? 0.2;
  const release = taper.release ?? 1;
  return (taper.strokeWidth / 2) * (pressure + (release - pressure) * t);
}

export function brushGrainScale(strokeWidth: number, grain: number): number {
  return strokeWidth * GRAIN_RATIO * grain;
}

export function brushReach(strokeWidth: number, grain: number): number {
  return strokeWidth / 2 + brushGrainScale(strokeWidth, grain) / 2;
}

export function brushFilterId(
  seed: string,
  strokeWidth: number,
  grain: number,
): string {
  return `remocn-brush-${Math.floor(hash01(`${seed}:${strokeWidth}:${grain}`) * 1e9)}`;
}

export function sampleCubic(
  from: BrushPoint,
  c1: BrushPoint,
  c2: BrushPoint,
  to: BrushPoint,
  points = 32,
): BrushPoint[] {
  const count = Math.max(2, points);
  return Array.from({ length: count }, (_, i) => {
    const t = i / (count - 1);
    const u = 1 - t;
    const a = u * u * u;
    const b = 3 * u * u * t;
    const c = 3 * u * t * t;
    const d = t * t * t;
    return {
      x: a * from.x + b * c1.x + c * c2.x + d * to.x,
      y: a * from.y + b * c1.y + c * c2.y + d * to.y,
    };
  });
}

export function sampleLine(
  from: BrushPoint,
  to: BrushPoint,
  points = 8,
): BrushPoint[] {
  const count = Math.max(2, points);
  return Array.from({ length: count }, (_, i) => {
    const t = i / (count - 1);
    return {
      x: from.x + (to.x - from.x) * t,
      y: from.y + (to.y - from.y) * t,
    };
  });
}

const normalAt = (points: BrushPoint[], i: number): BrushPoint => {
  const before = points[i - 1] ?? points[i];
  const after = points[i + 1] ?? points[i];
  const tx = after.x - before.x;
  const ty = after.y - before.y;
  const length = Math.hypot(tx, ty) || 1;
  return { x: -ty / length, y: tx / length };
};

const curveSegments = (points: BrushPoint[]): string =>
  points
    .slice(0, -1)
    .map((p1, i) => {
      const p0 = points[i - 1] ?? p1;
      const p2 = points[i + 1];
      const p3 = points[i + 2] ?? p2;
      return `C ${p1.x + (p2.x - p0.x) / 6} ${p1.y + (p2.y - p0.y) / 6}, ${p2.x - (p3.x - p1.x) / 6} ${p2.y - (p3.y - p1.y) / 6}, ${p2.x} ${p2.y}`;
    })
    .join(" ");

export function brushRibbon(
  spine: BrushPoint[],
  options: BrushTaper & { progress?: number },
): string {
  const progress = options.progress ?? 1;
  const drawn = Math.max(2, Math.round(progress * (spine.length - 1)) + 1);

  const left: BrushPoint[] = [];
  const right: BrushPoint[] = [];
  for (let i = 0; i < drawn; i++) {
    const half = brushHalfWidth(options, i / (spine.length - 1));
    const normal = normalAt(spine, i);
    left.push({
      x: spine[i].x + normal.x * half,
      y: spine[i].y + normal.y * half,
    });
    right.push({
      x: spine[i].x - normal.x * half,
      y: spine[i].y - normal.y * half,
    });
  }
  const back = right.slice().reverse();

  return `M ${left[0].x} ${left[0].y} ${curveSegments(left)} L ${back[0].x} ${back[0].y} ${curveSegments(back)} Z`;
}

export function BrushGrain({
  seed,
  strokeWidth,
  grain,
}: {
  seed: string;
  strokeWidth: number;
  grain: number;
}) {
  return (
    <defs>
      <filter
        id={brushFilterId(seed, strokeWidth, grain)}
        x="-30%"
        y="-30%"
        width="160%"
        height="160%"
      >
        <feTurbulence
          type="fractalNoise"
          baseFrequency={GRAIN_FREQUENCY}
          numOctaves={GRAIN_OCTAVES}
          seed={Math.floor(hash01(`${seed}:grain`) * 1000)}
          result="brushGrain"
        />
        <feDisplacementMap
          in="SourceGraphic"
          in2="brushGrain"
          scale={brushGrainScale(strokeWidth, grain)}
          xChannelSelector="R"
          yChannelSelector="G"
        />
      </filter>
    </defs>
  );
}

"use client";

import type React from "react";
import { AbsoluteFill } from "remotion";
import {
  type CanvasFilterProps,
  makeCanvasFilter,
  makeFilterShader,
} from "@/lib/remocn/canvas-presentation";

export type CameraLensProps = {
  softness?: number;
  bloom?: number;
  aberration?: number;
  vignette?: number;
  distortion?: number;
};

const DEFAULTS = {
  softness: 0.5,
  bloom: 0.5,
  aberration: 0.5,
  vignette: 0.5,
  distortion: 0.05,
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_aspect;
uniform float u_softness;
uniform float u_bloom;
uniform float u_aberration;
uniform float u_vignette;
uniform float u_distortion;

in vec2 v_uv;
out vec4 outColor;

const int SOFT_TAPS = 6;
const int GLARE_TAPS = 8;
const float GOLDEN = 2.39996323;

vec2 lensUv(vec2 direction, float distance) {
  vec2 q = direction * distance;
  q.x /= u_aspect;
  return q * 0.5 + 0.5;
}

vec2 spiral(int index, int count, float radius, float turn) {
  float angle = float(index) * GOLDEN + turn;
  float step = sqrt((float(index) + 0.5) / float(count)) * radius;
  return vec2(cos(angle) * step / u_aspect, sin(angle) * step);
}

vec4 softSample(vec2 uv, float radius) {
  vec4 sum = texture(u_scene, uv);
  if (radius <= 0.00002) {
    return sum;
  }
  for (int i = 0; i < SOFT_TAPS; i++) {
    sum += texture(u_scene, uv + spiral(i, SOFT_TAPS, radius, 0.0));
  }
  return sum / float(SOFT_TAPS + 1);
}

void main() {
  vec2 p = (v_uv - 0.5) * 2.0;
  p.x *= u_aspect;

  float span = sqrt(u_aspect * u_aspect + 1.0);
  float reach = length(p);
  float radius = reach / span;
  vec2 direction = reach > 0.0001 ? p / reach : vec2(0.0);

  float bend = 1.0 / (1.0 + clamp(u_distortion, 0.0, 1.0) * radius * radius);
  float focused = reach * bend;
  vec2 base = lensUv(direction, focused);

  float soft = u_softness * 0.011 * smoothstep(0.22, 1.0, radius);
  float split = u_aberration * 0.0035 * radius;

  vec4 mid = softSample(base, soft);
  float red = softSample(lensUv(direction, focused * (1.0 + split)), soft).r;
  float blue = softSample(lensUv(direction, focused * (1.0 - split)), soft).b;
  vec3 color = vec3(red, mid.g, blue);

  vec3 glare = vec3(0.0);
  for (int i = 0; i < GLARE_TAPS; i++) {
    vec3 tap =
      texture(u_scene, base + spiral(i, GLARE_TAPS, u_bloom * 0.026, 0.7)).rgb;
    glare += max(tap - 0.62, vec3(0.0));
  }
  color += (glare / float(GLARE_TAPS)) * u_bloom * 1.4;

  float falloff = pow(cos(min(radius, 1.0) * 0.55), 4.0);
  color *= mix(1.0, falloff, clamp(u_vignette, 0.0, 1.5));

  outColor = vec4(clamp(color, 0.0, 1.0), mid.a);
}`;

const shader = makeFilterShader<CameraLensProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const {
      softness = DEFAULTS.softness,
      bloom = DEFAULTS.bloom,
      aberration = DEFAULTS.aberration,
      vignette = DEFAULTS.vignette,
      distortion = DEFAULTS.distortion,
    } = passedProps;
    gl.uniform1f(uniform("u_softness"), softness);
    gl.uniform1f(uniform("u_bloom"), bloom);
    gl.uniform1f(uniform("u_aberration"), aberration);
    gl.uniform1f(uniform("u_vignette"), vignette);
    gl.uniform1f(uniform("u_distortion"), distortion);
  },
);

const CameraLensFallback: React.FC<CameraLensProps & CanvasFilterProps> = ({
  children,
  bloom = DEFAULTS.bloom,
  vignette = DEFAULTS.vignette,
}) => (
  <AbsoluteFill>
    <AbsoluteFill>{children}</AbsoluteFill>
    <AbsoluteFill
      style={{
        filter: `blur(${6 * bloom}px) brightness(1.5) contrast(1.3)`,
        mixBlendMode: "screen",
        opacity: 0.3 * bloom,
      }}
    >
      {children}
    </AbsoluteFill>
    <AbsoluteFill
      style={{
        background:
          "radial-gradient(ellipse 78% 76% at 50% 50%, transparent 52%, rgba(0, 0, 0, 0.5) 100%)",
        opacity: Math.min(vignette, 1),
      }}
    />
  </AbsoluteFill>
);

export const CameraLens = makeCanvasFilter<CameraLensProps>({
  shader,
  fallback: CameraLensFallback,
});

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

export type CaretWipeProps = {
  /** Sweep direction. `right` types the screen left→right; `left` reverses it. */
  direction?: "left" | "right";
  /** The caret's color — the remocn lime by default. */
  caretColor?: string;
  /** Caret bar width in px. */
  caretWidth?: number;
  /** Caret bar height as a fraction of frame height (0–1), vertically centered. */
  caretHeight?: number;
};

// ---------------------------------------------------------------------------
// caret-wipe — a typographic scene transition.
//
// A single tall caret (the remocn text cursor) sweeps across the frame in one
// eased pass. The caret IS the wipe boundary: the region it has PASSED shows
// the incoming scene (freshly "typed in" — it settles down and un-blurs just
// behind the caret), while the region it has NOT reached still shows the
// outgoing scene (being "backspaced" — it lifts and blurs as it's consumed).
//
// Both scenes share whatever backdrop sits behind the TransitionSeries, so the
// complementary clips never expose a seam. Pure frame-driven interpolate — no
// CSS keyframes — so it seeks correctly and renders identically every time.
// ---------------------------------------------------------------------------
const CaretWipePresentation: React.FC<
  TransitionPresentationComponentProps<CaretWipeProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const {
    direction = "right",
    caretColor = "#C3E88D",
    caretWidth = 3,
    caretHeight = 0.5,
  } = passedProps;

  const entering = presentationDirection === "entering";
  const p = presentationProgress;
  const goingRight = direction === "right";

  // Eased sweep so the caret decelerates as it lands the last column.
  const eased = interpolate(p, [0, 1], [0, 1], {
    ...clampOpts,
    easing: Easing.bezier(0.65, 0, 0.35, 1),
  });
  // Caret position as a percent of frame width; the wipe boundary.
  const caretX = goingRight ? eased * 100 : (1 - eased) * 100;

  if (!entering) {
    // Outgoing: keep only the column the caret hasn't reached yet, and let it
    // lift + blur as it's consumed (backspaced).
    const keep = goingRight
      ? `inset(0 0 0 ${caretX}%)` // keep the right band [caretX, 100]
      : `inset(0 ${100 - caretX}% 0 0)`; // keep the left band [0, caretX]
    return (
      <AbsoluteFill
        style={{
          clipPath: keep,
          WebkitClipPath: keep,
          translate: `0 ${interpolate(p, [0, 1], [0, -6], clampOpts)}px`,
          filter: `blur(${interpolate(p, [0.1, 1], [0, 4], clampOpts)}px)`,
        }}
      >
        {children}
      </AbsoluteFill>
    );
  }

  // Incoming: reveal only the column the caret has already passed, and let it
  // settle down + sharpen just behind the caret (typed in).
  const reveal = goingRight
    ? `inset(0 ${100 - caretX}% 0 0)` // reveal the left band [0, caretX]
    : `inset(0 0 0 ${caretX}%)`; // reveal the right band [caretX, 100]

  // The caret fades in at the very start and out at the very end so it never
  // pops on/off at the transition's frame edges.
  const caretOpacity = interpolate(
    p,
    [0, 0.08, 0.92, 1],
    [0, 1, 1, 0],
    clampOpts,
  );

  return (
    <AbsoluteFill>
      {/* Freshly typed content, clipped to the passed column. */}
      <AbsoluteFill
        style={{
          clipPath: reveal,
          WebkitClipPath: reveal,
          translate: `0 ${interpolate(p, [0, 1], [3, 0], clampOpts)}px`,
          filter: `blur(${interpolate(p, [0, 0.8], [2, 0], clampOpts)}px)`,
        }}
      >
        {children}
      </AbsoluteFill>

      {/* The caret — drawn on top, unclipped, only in the entering pass so it
          appears exactly once. */}
      <AbsoluteFill style={{ pointerEvents: "none", opacity: caretOpacity }}>
        <div
          style={{
            position: "absolute",
            left: `${caretX}%`,
            top: `${(1 - caretHeight) * 50}%`,
            height: `${caretHeight * 100}%`,
            width: caretWidth,
            translate: "-50%",
            background: caretColor,
            borderRadius: caretWidth,
            boxShadow: `0 0 18px ${caretColor}, 0 0 6px ${caretColor}`,
          }}
        />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export function caretWipe(
  props: CaretWipeProps = {},
): TransitionPresentation<CaretWipeProps> {
  return {
    component: CaretWipePresentation,
    props,
  };
}

