"use client";

import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export interface ConfettiProps {
  /** Number of confetti pieces. */
  particleCount?: number;
  colors?: string[];
  /** Burst origin as a 0..1 fraction of the canvas. */
  originX?: number;
  originY?: number;
  /** Frame the burst fires on. */
  startFrame?: number;
  /** Lifetime of the burst, in frames. */
  lifetime?: number;
  /** Initial launch speed (px/frame at the 720px reference height). */
  power?: number;
  /** Downward acceleration (px/frame² at the 720px reference height). */
  gravity?: number;
  /** Base piece size in reference px. */
  size?: number;
  /** PRNG seed — same seed renders an identical burst every time. */
  seed?: number;
}

export interface Particle {
  angle: number;
  speed: number;
  color: string;
  size: number;
  rot0: number;
  spin: number;
  drift: number;
}

const DEFAULT_COLORS = [
  "#1d9bf0",
  "#ff5da2",
  "#ffd23f",
  "#22c55e",
  "#a855f7",
  "#ff7a45",
];

// --- Pure helpers (unit-tested) -------------------------------------------

/** Deterministic PRNG (mulberry32) — returns a function yielding [0, 1). */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Build a deterministic particle set for a seed (stable across renders). */
export function makeParticles({
  count,
  seed,
  colors,
}: {
  count: number;
  seed: number;
  colors: string[];
}): Particle[] {
  const rand = mulberry32(seed);
  const palette = colors.length > 0 ? colors : DEFAULT_COLORS;
  const out: Particle[] = [];
  for (let i = 0; i < count; i++) {
    const angle = rand() * Math.PI * 2;
    const speed = 0.35 + 0.65 * rand();
    out.push({
      angle,
      speed,
      color: palette[Math.floor(rand() * palette.length)],
      size: 0.7 + 0.6 * rand(),
      rot0: rand() * Math.PI * 2,
      spin: (rand() - 0.5) * 0.6,
      drift: (rand() - 0.5) * 2,
    });
  }
  return out;
}

/** Opacity envelope over a particle's lifetime: quick fade-in, slow fade-out. */
export function particleOpacity(tt: number, lifetime: number): number {
  if (tt < 0 || tt > lifetime) return 0;
  const fadeIn = interpolate(tt, [0, 4], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const fadeOut = interpolate(tt, [lifetime * 0.7, lifetime], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return Math.min(fadeIn, fadeOut);
}

// --- Component -------------------------------------------------------------

export function Confetti({
  particleCount = 140,
  colors = DEFAULT_COLORS,
  originX = 0.5,
  originY = 0.5,
  startFrame = 0,
  lifetime = 90,
  power = 17,
  gravity = 0.45,
  size = 13,
  seed = 1,
}: ConfettiProps) {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const tt = frame - startFrame;
  if (tt < 0 || tt > lifetime) return null;

  const sc = height / 720;
  const ox = width * originX;
  const oy = height * originY;
  const particles = makeParticles({ count: particleCount, seed, colors });

  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      {particles.map((p, i) => {
        const opacity = particleOpacity(tt, lifetime);
        if (opacity <= 0) return null;

        const vx = Math.cos(p.angle) * p.speed * power + p.drift;
        const vy = Math.sin(p.angle) * p.speed * power;
        const x = ox + vx * tt * sc;
        const y = oy + (vy * tt + 0.5 * gravity * tt * tt) * sc;
        const rot = p.rot0 + p.spin * tt;
        const flutter = Math.cos(p.rot0 + p.spin * tt * 1.6);
        const w = size * p.size * sc;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: x,
              top: y,
              width: w,
              height: w * 0.62,
              borderRadius: 2,
              background: p.color,
              opacity,
              translate: "-50% -50%",
              rotate: `${rot}rad`,
              scale: `${flutter} 1`,
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
}

"use client";

import type React from "react";
import { AbsoluteFill } from "remotion";
import {
  type CanvasFilterProps,
  makeCanvasFilter,
  makeFilterShader,
} from "@/lib/remocn/canvas-presentation";

export type CrtScreenProps = {
  curvature?: number;
  scanlines?: number;
  maskScale?: number;
  vignette?: number;
};

const DEFAULTS = {
  curvature: 1,
  scanlines: 1,
  maskScale: 2,
  vignette: 1,
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_frame;
uniform float u_curvature;
uniform float u_scanlines;
uniform float u_mask_scale;
uniform float u_vignette;

in vec2 v_uv;
out vec4 outColor;

const float PI = 3.141592653589793;
const float SCAN_LINES = 240.0;

vec2 warpTube(vec2 uv, float k) {
  vec2 p = uv * 2.0 - 1.0;
  float x2 = p.x * p.x;
  float y2 = p.y * p.y;
  p.x *= 1.0 + k * 0.11 * y2;
  p.y *= 1.0 + k * 0.17 * x2;
  p /= 1.0 + k * 0.045;
  return p * 0.5 + 0.5;
}

vec3 phosphorMask(float x, float scale) {
  float sub = mod(floor(x / max(scale, 1.0)), 3.0);
  vec3 lit = vec3(
    step(sub, 0.5),
    step(0.5, sub) * step(sub, 1.5),
    step(1.5, sub)
  );
  return mix(vec3(0.34), vec3(1.0), lit);
}

void main() {
  vec2 uv = warpTube(v_uv, u_curvature);

  vec2 edge =
    smoothstep(vec2(0.0), vec2(0.005), uv) *
    smoothstep(vec2(0.0), vec2(0.005), 1.0 - uv);
  float inside = edge.x * edge.y;

  vec4 base = texture(u_scene, uv);

  vec3 spread = vec3(0.0);
  for (int i = -2; i <= 2; i++) {
    spread += texture(u_scene, uv + vec2(float(i) * 0.0018, 0.0)).rgb;
  }
  spread /= 5.0;
  vec3 bloom = max(spread - 0.5, vec3(0.0));

  vec3 color = base.rgb;
  color *= phosphorMask(gl_FragCoord.x, u_mask_scale);
  color += bloom * 0.75;

  float scan = mix(1.0, 0.5 + 0.5 * cos(uv.y * SCAN_LINES * PI * 2.0), 0.55);
  color *= mix(1.0, scan, clamp(u_scanlines, 0.0, 1.5));

  vec2 vc = uv * 2.0 - 1.0;
  float radius = length(vc * vec2(0.86, 1.0));
  color *= mix(1.0, smoothstep(1.6, 0.35, radius), clamp(u_vignette, 0.0, 1.5));

  color *= 1.0 + 0.012 * sin(u_frame * PI / 30.0);
  color *= inside;

  outColor = vec4(clamp(color, 0.0, 1.0), max(base.a, 1.0 - inside));
}`;

const shader = makeFilterShader<CrtScreenProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const {
      curvature = DEFAULTS.curvature,
      scanlines = DEFAULTS.scanlines,
      maskScale = DEFAULTS.maskScale,
      vignette = DEFAULTS.vignette,
    } = passedProps;
    gl.uniform1f(uniform("u_curvature"), curvature);
    gl.uniform1f(uniform("u_scanlines"), scanlines);
    gl.uniform1f(uniform("u_mask_scale"), maskScale);
    gl.uniform1f(uniform("u_vignette"), vignette);
  },
);

const CrtScreenFallback: React.FC<CrtScreenProps & CanvasFilterProps> = ({
  children,
  scanlines = DEFAULTS.scanlines,
  vignette = DEFAULTS.vignette,
}) => (
  <AbsoluteFill>
    <AbsoluteFill style={{ filter: "saturate(1.1) contrast(1.06)" }}>
      {children}
    </AbsoluteFill>
    <AbsoluteFill
      style={{
        background:
          "repeating-linear-gradient(to bottom, rgba(0, 0, 0, 0.34) 0px, rgba(0, 0, 0, 0.34) 1.5px, transparent 1.5px, transparent 3px)",
        opacity: Math.min(scanlines, 1),
      }}
    />
    <AbsoluteFill
      style={{
        background:
          "radial-gradient(ellipse 82% 78% at 50% 50%, transparent 45%, rgba(0, 0, 0, 0.72) 100%)",
        opacity: Math.min(vignette, 1),
      }}
    />
  </AbsoluteFill>
);

export const CrtScreen = makeCanvasFilter<CrtScreenProps>({
  shader,
  fallback: CrtScreenFallback,
});

"use client";

import type React from "react";
import { useCurrentFrame } from "remotion";
import { DEFAULT_STEP, hashRange, qstep } from "@/lib/remocn/stop-motion";

const GRAVITY = 0.9;
const FLIGHT_SHRINK = 0.5;
const EXIT_OPACITY = 0.4;

const FOLD_TILT = 46;
const WAD_REACH = 0.27;
const WAD_SPREAD = 0.07;
const ANGLE_JITTER = 0.22;
const SCALE_SPREAD = 0.25;
const DEFAULT_RANDOMNESS = 0.6;
const DEFAULT_LAYERS = 2;
const LAYER_TILT_FLOOR = 0.45;
const FACET_SIZE = 0.5;
const FACET_CAP = 0.5;

const TONE_PATTERN = [0, 1, 3, 1, 0, 2, 1, 2, 0];

const TONES = [
  { lit: "rgba(255,255,255,0.66)", dark: "rgba(255,255,255,0.18)" },
  { lit: "rgba(255,255,255,0.30)", dark: "rgba(38,36,44,0.10)" },
  { lit: "rgba(255,255,255,0.08)", dark: "rgba(38,36,44,0.20)" },
  { lit: "rgba(38,36,44,0.06)", dark: "rgba(38,36,44,0.30)" },
];

const LIGHT_ANGLE = -55;
const CREASE_BLEND = 9;

export type CrumplePhase = "idle" | "crumple" | "toss" | "gone";

export type CrumplePose = {
  phase: CrumplePhase;
  crush: number;
  scale: number;
  rotate: number;
  x: number;
  y: number;
  opacity: number;
};

export type CrumpleSegment = {
  clip: [number, number][];
  origin: [number, number];
  dx: number;
  dy: number;
  scale: number;
  rotate: number;
  tone: number;
  crease: number;
};

export type CrumpleTossTiming = {
  at: number;
  crumpleSteps?: number;
  tossSteps?: number;
  direction?: number;
  distance?: number;
  spin?: number;
  crushTo?: number;
  seed?: string;
  step?: number;
};

const rayToEdge = (
  angle: number,
  halfWidth: number,
  halfHeight: number,
): [number, number] => {
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  const t = Math.min(
    halfWidth / (Math.abs(cos) || 1e-9),
    halfHeight / (Math.abs(sin) || 1e-9),
  );
  return [cos * t, sin * t];
};

const normalize = (angle: number) => {
  const turn = Math.PI * 2;
  return ((angle % turn) + turn) % turn;
};

const shrinkToward = (
  [x, y]: [number, number],
  factor: number,
): [number, number] => [x * factor, y * factor];

const averageOf = (points: [number, number][]): [number, number] => [
  points.reduce((sum, p) => sum + p[0], 0) / points.length,
  points.reduce((sum, p) => sum + p[1], 0) / points.length,
];

export function crumpleSegments(args: {
  width: number;
  height: number;
  segments?: number;
  layers?: number;
  crushTo?: number;
  randomness?: number;
  seed?: string;
}): CrumpleSegment[] {
  const count = Math.max(3, Math.round(args.segments ?? 9));
  const layers = Math.max(1, Math.round(args.layers ?? DEFAULT_LAYERS));
  const crushTo = args.crushTo ?? 0.34;
  const chaos = Math.min(1, Math.max(0, args.randomness ?? DEFAULT_RANDOMNESS));
  const seed = args.seed ?? "toss";
  const halfWidth = args.width / 2;
  const halfHeight = args.height / 2;
  const wad = Math.min(args.width, args.height) * crushTo;

  const angles = Array.from(
    { length: count },
    (_, i) =>
      (i / count) * Math.PI * 2 +
      hashRange(`${seed}:ang${i}`, -ANGLE_JITTER, ANGLE_JITTER) * chaos,
  );

  const corners: [number, number][] = [
    [halfWidth, halfHeight],
    [-halfWidth, halfHeight],
    [-halfWidth, -halfHeight],
    [halfWidth, -halfHeight],
  ];

  const toPercent = ([x, y]: [number, number]): [number, number] => [
    ((x + halfWidth) / args.width) * 100,
    ((y + halfHeight) / args.height) * 100,
  ];

  const panels: CrumpleSegment[] = [];

  angles.forEach((angle, i) => {
    const nextAngle =
      angles[(i + 1) % count] + (i === count - 1 ? Math.PI * 2 : 0);
    const from = rayToEdge(angle, halfWidth, halfHeight);
    const to = rayToEdge(nextAngle, halfWidth, halfHeight);

    const span = normalize(nextAngle - angle);
    const between = corners
      .map((corner): [[number, number], number] => [
        corner,
        normalize(Math.atan2(corner[1], corner[0]) - angle),
      ])
      .filter(([, spanned]) => spanned > 0 && spanned < span)
      .sort((a, b) => a[1] - b[1])
      .map(([corner]) => corner);

    const rim: [number, number][] = [from, ...between, to];

    for (let layer = 0; layer < layers; layer++) {
      const inner = layer / layers;
      const outer = (layer + 1) / layers;
      const depth = (layer + 1) / layers;
      const shape: [number, number][] =
        layer === 0
          ? [[0, 0], ...rim.map((point) => shrinkToward(point, outer))]
          : [
              ...rim.map((point) => shrinkToward(point, outer)),
              ...[...rim].reverse().map((point) => shrinkToward(point, inner)),
            ];

      const centroid = averageOf(shape);
      const extent =
        Math.max(
          ...shape.map((point) =>
            Math.hypot(point[0] - centroid[0], point[1] - centroid[1]),
          ),
        ) || 1;
      const key = `${seed}:${i}:${layer}`;

      const reach =
        wad *
        (WAD_REACH * depth +
          hashRange(`${key}:reach`, -WAD_SPREAD, WAD_SPREAD) * chaos * depth);
      const heading = Math.atan2(centroid[1], centroid[0]);

      panels.push({
        clip: shape.map(toPercent),
        origin: toPercent(centroid),
        dx: Math.cos(heading) * reach - centroid[0],
        dy: Math.sin(heading) * reach - centroid[1],
        scale:
          Math.min(FACET_CAP, (wad * FACET_SIZE) / extent) *
          (1 + hashRange(`${key}:size`, -SCALE_SPREAD, SCALE_SPREAD) * chaos),
        rotate:
          chaos === 0
            ? 0
            : hashRange(`${seed}:tilt${i}`, -FOLD_TILT, FOLD_TILT) *
              chaos *
              (LAYER_TILT_FLOOR + (1 - LAYER_TILT_FLOOR) * depth),
        tone: Math.min(
          TONES.length - 1,
          TONE_PATTERN[panels.length % TONE_PATTERN.length] +
            Math.ceil((1 - depth) * 2),
        ),
        crease: 0.5 + hashRange(`${key}:crease`, -0.2, 0.2) * chaos,
      });
    }
  });

  return panels;
}

export function creaseShading(
  piece: Pick<CrumpleSegment, "tone" | "rotate" | "crease">,
  crush: number,
): string {
  const tone = TONES[piece.tone];
  const fold = piece.crease * 100;
  const lit = Math.max(0, fold - CREASE_BLEND).toFixed(1);
  const dark = Math.min(100, fold + CREASE_BLEND).toFixed(1);
  const angle = (LIGHT_ANGLE - piece.rotate * crush).toFixed(1);
  return `linear-gradient(${angle}deg, ${tone.lit} 0%, ${tone.lit} ${lit}%, ${tone.dark} ${dark}%, ${tone.dark} 100%)`;
}

export function crumpleTossLanding(options?: {
  direction?: number;
  distance?: number;
}): { x: number; y: number } {
  const distance = options?.distance ?? 900;
  const radians = ((options?.direction ?? -35) * Math.PI) / 180;
  return {
    x: distance * Math.cos(radians),
    y: distance * Math.sin(radians) + GRAVITY * distance,
  };
}

export function crumpleTossPose(
  args: CrumpleTossTiming & { frame: number },
): CrumplePose {
  const crumpleSteps = args.crumpleSteps ?? 4;
  const tossSteps = args.tossSteps ?? 5;
  const direction = args.direction ?? -35;
  const distance = args.distance ?? 900;
  const spin = args.spin ?? 220;
  const step = args.step ?? DEFAULT_STEP;

  if (args.frame < args.at) {
    return {
      phase: "idle",
      crush: 0,
      scale: 1,
      rotate: 0,
      x: 0,
      y: 0,
      opacity: 1,
    };
  }

  const pose = qstep(args.frame - args.at, step);

  if (pose < crumpleSteps) {
    return {
      phase: "crumple",
      crush: (pose + 1) / crumpleSteps,
      scale: 1,
      rotate: 0,
      x: 0,
      y: 0,
      opacity: 1,
    };
  }

  if (pose < crumpleSteps + tossSteps) {
    const t = (pose - crumpleSteps + 1) / tossSteps;
    const radians = (direction * Math.PI) / 180;
    return {
      phase: "toss",
      crush: 1,
      scale: 1 - FLIGHT_SHRINK * t,
      rotate: spin * t,
      x: distance * Math.cos(radians) * t,
      y: distance * Math.sin(radians) * t + GRAVITY * distance * t * t,
      opacity: t === 1 ? EXIT_OPACITY : 1,
    };
  }

  return {
    phase: "gone",
    crush: 1,
    scale: 0,
    rotate: 0,
    x: 0,
    y: 0,
    opacity: 0,
  };
}

export interface CrumpleTossProps extends CrumpleTossTiming {
  children: React.ReactNode;
  width: number;
  height: number;
  segments?: number;
  layers?: number;
  randomness?: number;
}

export function CrumpleToss({
  children,
  width,
  height,
  segments,
  layers,
  randomness,
  ...timing
}: CrumpleTossProps) {
  const frame = useCurrentFrame();
  const pose = crumpleTossPose({ frame, ...timing });
  if (pose.phase === "gone") return null;

  const pieces = crumpleSegments({
    width,
    height,
    segments,
    layers,
    randomness,
    crushTo: timing.crushTo,
    seed: timing.seed,
  });
  const c = pose.crush;

  return (
    <div
      style={{
        position: "relative",
        width,
        height,
        transformOrigin: "center",
        opacity: pose.opacity,
        translate: `${pose.x}px ${pose.y}px`,
        rotate: `${pose.rotate}deg`,
        scale: `${pose.scale}`,
      }}
    >
      {pieces.map((piece, i) => (
        <div
          key={`piece:${i}`}
          style={{
            position: "absolute",
            inset: 0,
            clipPath: `polygon(${piece.clip.map(([x, y]) => `${x}% ${y}%`).join(", ")})`,
            transformOrigin: `${piece.origin[0]}% ${piece.origin[1]}%`,
            translate: `${piece.dx * c}px ${piece.dy * c}px`,
            rotate: `${piece.rotate * c}deg`,
            scale: `${1 + (piece.scale - 1) * c}`,
            filter:
              c > 0
                ? `drop-shadow(0 0 ${0.6 * c}px rgba(38,36,44,0.55))`
                : undefined,
          }}
        >
          <div style={{ position: "absolute", inset: 0 }}>{children}</div>
          <div
            style={{
              position: "absolute",
              inset: 0,
              background: creaseShading(piece, c),
              opacity: c,
            }}
          />
        </div>
      ))}
    </div>
  );
}

"use client";

import type { ReactNode } from "react";
import { Easing, useCurrentFrame, useVideoConfig } from "remotion";

export interface CursorGravityProps {
  /** Custom content in a 300 × 88 reference-pixel slot. */
  children?: ReactNode;
  label?: string;
  /** Strength of the elastic neck and recoil, 0–1.5. */
  tension?: number;
  cursorColor?: string;
  color?: string;
  textColor?: string;
  backgroundColor?: string;
  speed?: number;
  className?: string;
}

export const cursorGravityLength = 151;
const DURATION = 180;
const finite = (value: number, fallback: number) =>
  Number.isFinite(value) ? value : fallback;
const clamp = (value: number) => Math.max(0, Math.min(1, value));
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const progress = (frame: number, start: number, end: number) =>
  clamp((frame - start) / (end - start));
const ease = Easing.bezier(0.65, 0, 0.35, 1);
const pullEase = Easing.bezier(0.12, 0.8, 0.22, 1);

/** Complete transition plus a one-second hold, in frames at 30 fps. */
export function getCursorGravityDuration({
  speed = 1,
}: Pick<CursorGravityProps, "speed"> = {}) {
  const rate = Math.max(0, finite(speed, 1));
  return rate === 0 ? 1 : Math.max(1, Math.ceil(DURATION / rate));
}

/** A pull advances sharply, pauses under load, then recoils before the next tug. */
function pullDistance(t: number, strength: number) {
  const keys = [
    [48, 0],
    [59, 116],
    [64, 116],
    [70, 116 - 30 * strength],
    [83, 292],
    [87, 292],
    [94, 292 - 42 * strength],
    [112, 772],
  ];
  if (t <= keys[0][0]) return 0;
  for (let i = 1; i < keys.length; i++) {
    const [start, a] = keys[i - 1];
    const [end, b] = keys[i];
    if (t <= end)
      return mix(a, b, (b > a ? pullEase : ease)(progress(t, start, end)));
  }
  return 772;
}

/** Pure, resolution-aware pose. The right edge is the real composition boundary. */
export function getCursorGravityState(
  frame: number,
  {
    width = 1280,
    height = 720,
    tension = 1,
  }: { width?: number; height?: number; tension?: number } = {},
) {
  const w = Math.max(1, finite(width, 1280));
  const h = Math.max(1, finite(height, 720));
  const unit = Math.min(w / 1280, h / 720);
  const t = Math.max(0, finite(frame, 0));
  const strength = Math.max(0, Math.min(1.5, finite(tension, 1)));
  const centerY = h * 0.5;
  const finalLeft = w / 2 - 150 * unit;
  const finalRight = w / 2 + 150 * unit;
  const edgeTip = w - 24 * unit;
  const distance = pullDistance(t, strength) / 772;
  const extraction = distance * (edgeTip - (finalLeft - 14 * unit));
  // The back of the button resists the first two tugs beyond the frame edge.
  const releaseTime = progress(t, 94, 132);
  // Closed-form damped spring stays continuous at fractional frames too.
  const springRelease =
    1 -
    Math.exp(-7 * releaseTime) *
      (Math.cos(10 * releaseTime) + 0.7 * Math.sin(10 * releaseTime));
  const release = mix(springRelease, 1, ease(progress(t, 122, 132)));
  const front = mix(w + 12 * unit, finalLeft, distance);
  const right = mix(w + 312 * unit - distance * 70 * unit, finalRight, release);
  const buttonWidth = Math.max(220 * unit, right - front);
  const strain = clamp((buttonWidth / (300 * unit) - 1) / 1.3) * strength;
  const wobble =
    t < 112
      ? 0
      : Math.sin((t - 112) * 0.48) *
        Math.exp(-(t - 112) * 0.14) *
        5 *
        unit *
        strength *
        (1 - progress(t, 132, 140));
  const y = centerY + wobble;
  const entry = ease(progress(t, 10, 39));
  const approach = ease(progress(t, 39, 48));
  const leave = ease(progress(t, 127, 151));
  const holdTip = mix(w * 0.28, edgeTip - 80 * unit, entry);
  const pullTip = edgeTip - extraction;
  const cursorX =
    t < 48 ? mix(holdTip, edgeTip, approach) : mix(pullTip, w * 0.25, leave);
  const cursorY =
    t < 39
      ? mix(h + 110 * unit, centerY + 70 * unit, entry)
      : t < 48
        ? mix(centerY + 70 * unit, centerY, approach)
        : mix(centerY, h + 110 * unit, leave);
  // Triangle points toward the edge while pulling; turns toward its exit afterward.
  const cursorAngle = t < 48 ? mix(-32, 0, approach) : mix(0, 115, leave);
  const effortPulse = (
    start: number,
    peak: number,
    hold: number,
    end: number,
  ) => ease(progress(t, start, peak)) * (1 - ease(progress(t, hold, end)));
  const cursorEffort =
    strength *
    (0.8 * effortPulse(48, 58, 64, 70) +
      effortPulse(70, 81, 87, 94) +
      1.15 * effortPulse(94, 100, 104, 118));
  return {
    frame: t,
    unit,
    front,
    right: front + buttonWidth,
    buttonWidth,
    centerY: y,
    strain,
    neckHeight: 88 * unit * (1 - 0.58 * strain),
    bodyHeight: 88 * unit * (1 - 0.17 * strain),
    cursorX,
    cursorY,
    cursorAngle,
    cursorEffort,
    attached: t >= 48 && t <= 121,
    tetherOpacity: progress(t, 46, 49) * (1 - progress(t, 115, 122)),
  };
}

/** The tip stays fixed; the rear bows backward as each tug builds effort. */
export function getGravityCursorPath(effort: number) {
  const load = Math.max(0, Math.min(1.725, finite(effort, 0)));
  const shoulder = -62 - 30 * load;
  const rear = -70 - 40 * load;
  const halfHeight = 26 - 4 * load;
  return `M -5 -4 Q 3 0 -5 4
    C -24 ${11.333 - load * 3} ${shoulder + 19} ${halfHeight - 7.333} ${shoulder} ${halfHeight}
    Q ${rear} ${halfHeight + 4} ${rear} ${halfHeight - 6}
    C ${rear} 4 ${rear - 18 * load} 8 ${rear - 18 * load} 0
    C ${rear - 18 * load} -8 ${rear} -4 ${rear} ${-halfHeight + 6}
    Q ${rear} ${-halfHeight - 4} ${shoulder} ${-halfHeight}
    C ${shoulder + 19} ${-halfHeight + 7.333} -24 ${-11.333 + load * 3} -5 -4 Z`;
}

/** Rounded rectangle with a narrow leading edge: the pull deforms the surface. */
export function getGravityButtonPath(
  state: ReturnType<typeof getCursorGravityState>,
) {
  const { buttonWidth: w, neckHeight, bodyHeight, unit } = state;
  const a = neckHeight / 2;
  const b = bodyHeight / 2;
  const r = Math.min(25 * unit, a * 0.9);
  const backRadius = 25 * unit;
  return `M ${r} ${-a}
    C ${w * 0.35} ${-a} ${w * 0.35} ${-b} ${w - backRadius} ${-b}
    Q ${w} ${-b} ${w} ${-b + backRadius}
    L ${w} ${b - backRadius} Q ${w} ${b} ${w - backRadius} ${b}
    C ${w * 0.35} ${b} ${w * 0.35} ${a} ${r} ${a}
    Q 0 ${a} 0 ${a - r} L 0 ${-a + r} Q 0 ${-a} ${r} ${-a} Z`;
}

export function CursorGravity({
  children,
  label = "Create something",
  tension = 1,
  cursorColor = "#fffaf0",
  color = "#fffaf0",
  textColor = "#32153c",
  backgroundColor = "#a800b7",
  speed = 1,
  className,
}: CursorGravityProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const t = frame * (30 / fps) * Math.max(0, finite(speed, 1));
  const state = getCursorGravityState(t, { width, height, tension });
  const { unit } = state;
  // Content travels with the material, without stretching the lettering.
  const contentUnit = unit * Math.min(1, state.buttonWidth / (300 * unit));
  const contentX = state.front + state.buttonWidth - 150 * contentUnit;
  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        backgroundColor,
        fontFamily: "Arial, sans-serif",
      }}
    >
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        aria-hidden="true"
        style={{ position: "absolute", inset: 0 }}
      >
        <path
          d={getGravityButtonPath(state)}
          transform={`translate(${state.front} ${state.centerY})`}
          fill={color}
        />
        <path
          d={`M ${state.cursorX + 2 * unit} ${state.cursorY} Q ${mix(state.cursorX, state.front, 0.5)} ${state.centerY} ${state.front + 2 * unit} ${state.centerY}`}
          fill="none"
          stroke={cursorColor}
          strokeWidth={2 * unit}
          strokeLinecap="round"
          opacity={state.tetherOpacity}
        />
      </svg>
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: 300,
          height: 88,
          translate: `${contentX - 150 * contentUnit}px ${state.centerY - 44 * contentUnit}px`,
          scale: contentUnit,
          transformOrigin: "top left",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 20,
          color: textColor,
          fontWeight: 600,
          fontSize: 23,
        }}
      >
        {children ?? (
          <>
            <span
              style={{
                maxWidth: 220,
                overflow: "hidden",
                whiteSpace: "nowrap",
                textOverflow: "ellipsis",
              }}
            >
              {label}
            </span>
            <svg width="22" height="22" viewBox="0 0 24 24" aria-hidden="true">
              <path
                d="M5 12H19M13 6L19 12L13 18"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </>
        )}
      </div>
      <svg
        width={190 * unit}
        height={70 * unit}
        viewBox="-180 -35 190 70"
        role="img"
        aria-label="Rounded triangular cursor"
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          translate: `${state.cursorX - 180 * unit}px ${state.cursorY - 35 * unit}px`,
          transform: `rotate(${state.cursorAngle}deg)`,
          transformOrigin: `${180 * unit}px ${35 * unit}px`,
        }}
      >
        <path d={getGravityCursorPath(state.cursorEffort)} fill={cursorColor} />
      </svg>
    </div>
  );
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill } from "remotion";
import {
  makeCanvasPresentation,
  makeSceneShader,
} from "@/lib/remocn/canvas-presentation";

export type DisplacementProps = {
  grid?: number;
  cellAspect?: number;
  shift?: number;
  aberration?: number;
  grain?: number;
  stagger?: number;
};

const DEFAULTS = {
  grid: 60,
  cellAspect: 1,
  shift: 1,
  aberration: 1,
  grain: 0.5,
  stagger: 0.45,
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_from;
uniform sampler2D u_to;
uniform float u_progress;
uniform float u_aspect;
uniform vec2 u_cells;
uniform float u_shift;
uniform float u_aberration;
uniform float u_grain;
uniform float u_stagger;

in vec2 v_uv;
out vec4 outColor;

const float PI = 3.141592653589793;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

void main() {
  vec2 cell = floor(v_uv * u_cells);
  float h1 = hash(cell);
  float h2 = hash(cell + 7.3);
  float h3 = hash(cell + 13.1);

  float delay = h3 * u_stagger;
  float phase =
    clamp((u_progress - delay) / max(1.0 - u_stagger, 0.1), 0.0, 1.0);
  float shear = sin(phase * PI);

  vec2 aim = vec2((h1 - 0.5) * 2.0, (h2 - 0.5) * 0.7);
  vec2 dir = aim / max(length(aim), 0.0001);
  vec2 slide = dir * shear * u_shift * 1.4;
  vec2 off = slide / u_cells;
  vec2 fringe = off * u_aberration * 0.35;

  float swap = smoothstep(0.34, 0.66, phase);

  vec4 mid = mix(
    texture(u_from, v_uv - off),
    texture(u_to, v_uv - off),
    swap
  );
  float red = mix(
    texture(u_from, v_uv - off - fringe).r,
    texture(u_to, v_uv - off - fringe).r,
    swap
  );
  float blue = mix(
    texture(u_from, v_uv - off + fringe).b,
    texture(u_to, v_uv - off + fringe).b,
    swap
  );

  vec4 col = vec4(red, mid.g, blue, mid.a);

  float tick = floor(u_progress * 30.0);
  float speck =
    hash(floor(v_uv * vec2(u_aspect, 1.0) * 460.0) + tick * 1.7) - 0.5;
  col.rgb += vec3(speck * u_grain * shear * 0.5) * col.a;
  col.rgb *= 1.0 - 0.12 * shear;

  outColor = col;
}`;

const shader = makeSceneShader<DisplacementProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, width, height, passedProps }) => {
    const {
      grid = DEFAULTS.grid,
      cellAspect = DEFAULTS.cellAspect,
      shift = DEFAULTS.shift,
      aberration = DEFAULTS.aberration,
      grain = DEFAULTS.grain,
      stagger = DEFAULTS.stagger,
    } = passedProps;
    const across = Math.max(grid, 4);
    const ratio = Math.max(cellAspect, 0.25);
    gl.uniform2f(
      uniform("u_cells"),
      across,
      Math.max((across * ratio * height) / width, 2),
    );
    gl.uniform1f(uniform("u_shift"), shift);
    gl.uniform1f(uniform("u_aberration"), aberration);
    gl.uniform1f(uniform("u_grain"), grain);
    gl.uniform1f(uniform("u_stagger"), Math.min(Math.max(stagger, 0), 0.85));
  },
);

const DisplacementFallback: React.FC<
  TransitionPresentationComponentProps<DisplacementProps>
> = ({ children, presentationProgress, presentationDirection }) => {
  const p = presentationProgress;
  const entering = presentationDirection === "entering";
  const t = entering ? p : 1 - p;
  const settle = Math.min(1, Math.max(0, (t - 0.3) / 0.4));
  const jolt = Math.max(0, Math.sin(t * Math.PI)) * 10;

  return (
    <AbsoluteFill
      style={{
        opacity: settle,
        translate: `${entering ? jolt : -jolt}px`,
      }}
    >
      {children}
    </AbsoluteFill>
  );
};

const presentation = makeCanvasPresentation<DisplacementProps>({
  shader,
  fallback: DisplacementFallback,
});

export function displacement(
  props: DisplacementProps = {},
): TransitionPresentation<DisplacementProps> {
  return presentation(props);
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill, interpolate } from "remotion";
import { ShaderDithering } from "@/components/remocn/shader-dithering";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

const coverEnvelope = (p: number) =>
  interpolate(p, [0, 0.3, 0.65, 1], [0, 1, 1, 0], clampOpts);

const coverChildOpacity = (p: number, entering: boolean) =>
  entering
    ? interpolate(p, [0.58, 0.66], [0, 1], clampOpts)
    : interpolate(p, [0.28, 0.36], [1, 0], clampOpts);

type DitherShape = NonNullable<
  React.ComponentProps<typeof ShaderDithering>["shape"]
>;

export type DitherDissolveProps = {
  colorBack?: string;
  colorFront?: string;
  shape?: DitherShape;
  speed?: number;
};

const DitherDissolvePresentation: React.FC<
  TransitionPresentationComponentProps<DitherDissolveProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const {
    colorBack = "#141318",
    colorFront = "#8f88ae",
    shape = "simplex",
    speed = 1.5,
  } = passedProps;
  const entering = presentationDirection === "entering";
  const p = presentationProgress;
  const size = interpolate(p, [0, 1], [1.6, 2.8], clampOpts);

  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ opacity: coverChildOpacity(p, entering) }}>
        {children}
      </AbsoluteFill>
      {entering ? (
        <AbsoluteFill
          style={{ opacity: coverEnvelope(p), pointerEvents: "none" }}
        >
          <ShaderDithering
            speed={speed}
            colorBack={colorBack}
            colorFront={colorFront}
            shape={shape}
            size={size}
          />
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

export function ditherDissolve(
  props: DitherDissolveProps = {},
): TransitionPresentation<DitherDissolveProps> {
  return {
    component: DitherDissolvePresentation,
    props,
  };
}

