  accentColor = "#a855f7",
  speed = 1,
  className,
}: EcosystemConstellationProps) {
  const frame = useCurrentFrame() * speed;
  const { fps } = useVideoConfig();

  const count = Math.max(
    3,
    Math.min(SATELLITE_BRANDS.length, Math.floor(satelliteCount)),
  );

  // Center pulse (0..1)
  const pulse = (Math.sin(frame / 12) + 1) / 2;
  const centerScale = 1 + pulse * 0.06;

  // Geometry
  const cx = 640;
  const cy = 360;
  const baseRadiusX = 230;
  const baseRadiusY = 180;
  const offscreenRadius = 1200; // 150% of width

  // Per-satellite assembly spring (staggered)
  const satellites = Array.from({ length: count }).map((_, i) => {
    const stagger = i * 4;
    const sp = spring({
      frame: frame - stagger,
      fps,
      config: { mass: 1.1, damping: 16, stiffness: 70 },
      durationInFrames: 50,
    });
    const radiusFactor = interpolate(sp, [0, 1], [offscreenRadius, 1]);

    // Slight elliptical variation per satellite
    const orbitOffset = i * 22;
    const rX = baseRadiusX + orbitOffset;
    const rY = baseRadiusY + orbitOffset * 0.7;
    // Different angular speed per orbit (slower for outer)
    const angularSpeed = 0.012 - i * 0.0008;
    const baseAngle = (i / count) * Math.PI * 2;
    const angle = baseAngle + frame * angularSpeed;

    // Use radiusFactor as a multiplier on the orbit radius
    const x = cx + Math.cos(angle) * rX * radiusFactor;
    const y = cy + Math.sin(angle) * rY * radiusFactor;

    // Data pulse: which satellite is currently "firing"
    const activeIdx = Math.floor(frame / 30) % count;
    const isActive = activeIdx === i;
    // Within the active 30-frame window, fade the line in/out
    const localFrame = frame - Math.floor(frame / 30) * 30;
    const lineOpacity = isActive
      ? interpolate(localFrame, [0, 8, 22, 30], [0.15, 0.9, 0.9, 0.15], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })
      : 0.15;
    const satScale = isActive
      ? interpolate(localFrame, [0, 8, 22, 30], [1, 1.1, 1.1, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })
      : 1;

    const brand = SATELLITE_BRANDS[i % SATELLITE_BRANDS.length];
    return {
      x,
      y,
      Logo: brand.Logo,
      color: brand.bg,
      lineOpacity,
      satScale,
      visible: sp > 0.02,
    };
  });

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        background: "transparent",
        fontFamily: FONT_FAMILY,
      }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox="0 0 1280 720"
        style={{ position: "absolute", inset: 0 }}
      >
        {/* Connection lines */}
        {satellites.map((s, i) => (
          <line
            key={`line-${i}`}
            x1={cx}
            y1={cy}
            x2={s.x}
            y2={s.y}
            stroke={accentColor}
            strokeWidth={2}
            strokeLinecap="round"
            opacity={s.visible ? s.lineOpacity : 0}
          />
        ))}

        {/* Center glow */}
        <circle
          cx={cx}
          cy={cy}
          r={70 + pulse * 8}
          fill={accentColor}
          opacity={0.12}
        />
        <circle
          cx={cx}
          cy={cy}
          r={50 + pulse * 4}
          fill={accentColor}
          opacity={0.2}
        />
      </svg>

      {/* Center logo */}
      <div
        style={{
          position: "absolute",
          left: cx,
          top: cy,
          width: 96,
          height: 96,
          marginLeft: -48,
          marginTop: -48,
          borderRadius: 24,
          background: `linear-gradient(180deg, ${accentColor} 0%, ${accentColor}cc 100%)`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: "white",
          fontWeight: 800,
          fontSize: 52,
          letterSpacing: "-0.05em",
          scale: `${centerScale}`,
          boxShadow: `0 0 60px ${accentColor}66, inset 0 1px 0 rgba(255,255,255,0.3)`,
          border: "1px solid rgba(255,255,255,0.15)",
        }}
      >
        {centerLabel}
      </div>

      {/* Satellites */}
      {satellites.map((s, i) => {
        const Logo = s.Logo;
        return (
          <div
            key={`sat-${i}`}
            style={{
              position: "absolute",
              left: s.x,
              top: s.y,
              width: 56,
              height: 56,
              marginLeft: -28,
              marginTop: -28,
              borderRadius: 14,
              background: `linear-gradient(180deg, ${s.color} 0%, ${s.color}dd 100%)`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              scale: `${s.satScale}`,
              boxShadow: `0 8px 30px ${s.color}66, inset 0 1px 0 rgba(255,255,255,0.18)`,
              border: "1px solid rgba(255,255,255,0.12)",
              opacity: s.visible ? 1 : 0,
              willChange: "transform",
            }}
          >
            <Logo />
          </div>
        );
      })}
    </div>
  );
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill } from "remotion";
import {
  makeCanvasPresentation,
  makeSceneShader,
} from "@/lib/remocn/canvas-presentation";

export type EmberBurnProps = {
  patches?: number;
  edgeSoftness?: number;
  contentBias?: number;
  heat?: number;
  glowColor?: string;
  emberAmount?: number;
};

const DEFAULTS = {
  patches: 5,
  edgeSoftness: 0.07,
  contentBias: 0.6,
  heat: 0.5,
  glowColor: "#ff7a2f",
  emberAmount: 0.5,
};

function hexToRgb(hex: string): [number, number, number] {
  const value = hex.replace("#", "");
  const full =
    value.length === 3
      ? value
          .split("")
          .map((c) => c + c)
          .join("")
      : value;
  const int = Number.parseInt(full, 16);
  if (Number.isNaN(int)) {
    return [1, 0.48, 0.18];
  }
  return [
    ((int >> 16) & 255) / 255,
    ((int >> 8) & 255) / 255,
    (int & 255) / 255,
  ];
}

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_from;
uniform sampler2D u_to;
uniform float u_progress;
uniform float u_aspect;
uniform float u_patches;
uniform float u_softness;
uniform float u_content;
uniform float u_heat;
uniform vec3 u_glow;
uniform float u_embers;

in vec2 v_uv;
out vec4 outColor;

const float EMBER_GRID = 110.0;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

float fbm(vec2 p) {
  float sum = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 5; i++) {
    sum += noise(p) * amp;
    p *= 2.03;
    amp *= 0.5;
  }
  return sum * 1.032;
}

float luma(vec3 c) {
  return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

void main() {
  vec2 skewed = vec2(v_uv.x * u_aspect, v_uv.y);
  float alive =
    smoothstep(0.0, 0.06, u_progress) * smoothstep(1.0, 0.94, u_progress);

  float brightness = luma(texture(u_from, v_uv).rgb);
  float field = clamp(
    clamp(fbm(skewed * u_patches), 0.0, 1.0) *
      (1.0 - u_content * brightness * 0.9),
    0.0,
    1.0
  );

  float soft = max(u_softness, 0.004);
  float margin = soft * 3.0 + 0.02;
  float front = mix(-margin, 1.0 + margin, pow(u_progress, 1.2));
  float depth = field - front;

  float intact = smoothstep(-soft, soft, depth);
  float arrived = 1.0 - intact;

  vec2 shimmer = vec2(
    noise(skewed * u_patches * 2.4 + vec2(0.0, u_progress * 3.1)) - 0.5,
    noise(skewed * u_patches * 2.4 + vec2(5.2, 1.7 + u_progress * 4.3)) - 0.5
  );
  float heatBand = depth / (soft * 6.0);
  float boil = exp(-heatBand * heatBand) * alive * u_heat * 0.14;
  vec4 from = texture(u_from, v_uv + shimmer * boil * intact);
  vec4 to = texture(u_to, v_uv - shimmer * boil * arrived);

  float ramp = depth / (soft * 2.2);
  float charBand = (ramp - 0.55) * 1.5;
  float moltenBand = (ramp + 0.55) * 1.5;
  float rimBand = depth / (soft * 1.1);
  float charred = intact * exp(-charBand * charBand) * alive;
  float molten = arrived * exp(-moltenBand * moltenBand) * alive;
  float rim = exp(-rimBand * rimBand);

  float since = clamp(-depth / (soft * 3.0), 0.0, 1.0);
  float emberBand = depth / (soft * 2.6);
  vec2 emberSpace = skewed + vec2(0.0, u_progress * 0.42);
  float cellSeed = hash(floor(emberSpace * EMBER_GRID));
  float ember =
    step(1.0 - u_embers * 0.08, cellSeed) *
    arrived *
    exp(-emberBand * emberBand) *
    alive;
  vec3 sparkSource = texture(u_from, v_uv + vec2(0.0, since * 0.07)).rgb;

  vec4 color = mix(to, from, intact);
  color.rgb *= 1.0 - charred * 0.92;
  color.rgb += (color.rgb * 1.2 + u_glow * 0.6) * molten;

  vec3 spark = mix(u_glow, sparkSource * 1.4 + u_glow * 0.3, 0.5);
  float light = min(rim * 0.85, 1.4);
  color.rgb += u_glow * light + spark * ember * 1.3;
  color.a = clamp(color.a + light + molten + ember, 0.0, 1.0);

  outColor = color;
}`;

const shader = makeSceneShader<EmberBurnProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const {
      patches = DEFAULTS.patches,
      edgeSoftness = DEFAULTS.edgeSoftness,
      contentBias = DEFAULTS.contentBias,
      heat = DEFAULTS.heat,
      glowColor = DEFAULTS.glowColor,
      emberAmount = DEFAULTS.emberAmount,
    } = passedProps;
    const glow = hexToRgb(glowColor);
    gl.uniform1f(uniform("u_patches"), patches);
    gl.uniform1f(uniform("u_softness"), edgeSoftness);
    gl.uniform1f(uniform("u_content"), contentBias);
    gl.uniform1f(uniform("u_heat"), heat);
    gl.uniform3f(uniform("u_glow"), glow[0], glow[1], glow[2]);
    gl.uniform1f(uniform("u_embers"), emberAmount);
  },
);

const EmberBurnFallback: React.FC<
  TransitionPresentationComponentProps<EmberBurnProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const { glowColor = DEFAULTS.glowColor } = passedProps;

  if (presentationDirection === "exiting") {
    return <AbsoluteFill>{children}</AbsoluteFill>;
  }

  const p = presentationProgress;
  const reveal = Math.min(1, Math.max(0, (p - 0.25) / 0.5));
  const flash = Math.max(0, Math.sin(p * Math.PI)) ** 0.6 * 0.4;

  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ opacity: reveal }}>{children}</AbsoluteFill>
      <AbsoluteFill
        style={{
          background: glowColor,
          mixBlendMode: "screen",
          opacity: flash,
          pointerEvents: "none",
        }}
      />
    </AbsoluteFill>
  );
};

const presentation = makeCanvasPresentation<EmberBurnProps>({
  shader,
  fallback: EmberBurnFallback,
});

export function emberBurn(
  props: EmberBurnProps = {},
): TransitionPresentation<EmberBurnProps> {
  return presentation(props);
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

export type FocusPullProps = {
  blur?: number;
};

const FocusPullPresentation: React.FC<
  TransitionPresentationComponentProps<FocusPullProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const { blur = 16 } = passedProps;
  const entering = presentationDirection === "entering";
  const p = presentationProgress;

  if (!entering) {
    const exitStyle: React.CSSProperties = {
      opacity: interpolate(p, [0.42, 0.68], [1, 0], {
        ...clampOpts,
        easing: Easing.bezier(0.42, 0, 0.58, 1),
      }),
      scale: `${interpolate(p, [0, 0.6], [1, 1.05], {
        ...clampOpts,
        easing: Easing.bezier(0.42, 0, 0.58, 1),
      })}`,
      filter: `blur(${interpolate(p, [0.05, 0.55], [0, blur], {
        ...clampOpts,
        easing: Easing.in(Easing.quad),
      })}px) brightness(${interpolate(p, [0.1, 0.55], [1, 1.3], clampOpts)})`,
    };
    return <AbsoluteFill style={exitStyle}>{children}</AbsoluteFill>;
  }

  const childStyle: React.CSSProperties = {
    opacity: interpolate(p, [0.32, 0.52], [0, 1], clampOpts),
    scale: `${interpolate(p, [0.35, 1], [0.97, 1], {
      ...clampOpts,
      easing: Easing.out(Easing.cubic),
    })}`,
    filter: `blur(${interpolate(p, [0.35, 0.9], [blur, 0], {
      ...clampOpts,
      easing: Easing.out(Easing.quad),
    })}px) brightness(${interpolate(p, [0.4, 0.85], [1.25, 1], clampOpts)})`,
  };

  return <AbsoluteFill style={childStyle}>{children}</AbsoluteFill>;
};

export function focusPull(
  props: FocusPullProps = {},
): TransitionPresentation<FocusPullProps> {
  return {
    component: FocusPullPresentation,
    props,
  };
}

