  return (
    <div
      style={{
        position: "absolute",
        left: cell.x,
        top: cell.y,
        translate: `-50% calc(-50% + ${y}px)`,
        opacity: progress,
        filter: `blur(${blur}px)`,
        willChange: "transform, opacity, filter",
      }}
    >
      <Avatar
        login={sponsor.login}
        avatarUrl={sponsor.avatarUrl}
        size={size}
        theme={theme}
        grayscale={1 - progress}
      />
    </div>
  );
});

function HeartGlyph({
  size,
  accent,
  draw,
  fill,
}: {
  size: number;
  accent: string;
  draw: number;
  fill: number;
}) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width={size}
      height={size}
    >
      <title>GitHub Sponsors</title>
      <path
        d={HEART_PATH}
        pathLength={1}
        fill={accent}
        fillOpacity={fill}
        stroke={accent}
        strokeWidth={1.4}
        strokeLinejoin="round"
        strokeLinecap="round"
        strokeDasharray={1}
        strokeDashoffset={1 - draw}
      />
    </svg>
  );
}

export function GitHubSponsors({
  account = "remocn",
  sponsors = SAMPLE_SPONSORS,
  accentColor = "#db61a2",
  speed = 1,
  theme = "light",
}: GitHubSponsorsProps) {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const t = THEMES[theme] ?? THEMES.light;
  const stageScale = Math.min(width / REF_W, height / REF_H);

  const count = sponsors.length;
  const avatarStep =
    count > 1 ? Math.min(AVATAR_STEP, AVATAR_WINDOW / (count - 1)) : 0;
  const cols = gridColumns(count);
  const rows = Math.max(1, Math.ceil(count / Math.max(1, cols)));
  const cellW = GRID_BOX_W / Math.max(1, cols);
  const cellH = GRID_BOX_H / rows;
  const avatarSize = Math.min(84, Math.min(cellW, cellH) * 0.76);

  const cells = useMemo(
    () => gridLayout(count, cols, cellW, cellH),
    [count, cols, cellW, cellH],
  );

  const draw = heartDrawProgress(frame, speed);
  const fillO = ramp(frame, speed, DRAW_END - 8, PULSE_END, Easing.linear);
  const pulse = heartPulseScale(frame, speed);
  const dock = ramp(frame, speed, HEART_DOCK_START, HEART_DOCK_END);

  const heartBase = 168;
  const heartScale = (1 - 0.62 * dock) * pulse;
  const heartDy = (HEART_HEADER_Y - HEART_START_Y) * dock;

  const ctaProgress = ramp(frame, speed, CTA_START, CTA_START + CTA_DUR);
  const ctaBlur = (1 - ctaProgress) * 10;
  const ctaY = (1 - ctaProgress) * 12;
  const accountOpacity = ramp(
    frame,
    speed,
    CTA_START + 8,
    CTA_START + CTA_DUR + 8,
  );

  return (
    <AbsoluteFill style={{ background: t.bg }}>
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: REF_W,
          height: REF_H,
          translate: "-50% -50%",
          scale: `${stageScale}`,
        }}
      >
        {sponsors.map((sponsor, i) => (
          <SponsorNode
            key={`node-${sponsor.login}-${i}`}
            sponsor={sponsor}
            cell={cells[i]}
            progress={ramp(
              frame,
              speed,
              AVATAR_START + i * avatarStep,
              AVATAR_START + i * avatarStep + AVATAR_DUR,
            )}
            size={avatarSize}
            theme={t}
          />
        ))}

        <div
          style={{
            position: "absolute",
            left: GRID_CX,
            top: HEART_START_Y,
            translate: `-50% calc(-50% + ${heartDy}px)`,
            scale: `${heartScale}`,
            width: heartBase,
            height: heartBase,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            willChange: "transform",
          }}
        >
          <HeartGlyph
            size={heartBase}
            accent={accentColor}
            draw={draw}
            fill={fillO}
          />
        </div>

        <div
          style={{
            position: "absolute",
            left: 0,
            top: 444,
            width: REF_W,
            height: 84,
          }}
        >
          <Sequence from={Math.round(THANK_START / speed)} layout="none">
            <SoftBlurIn
              text="Thank you"
              fontSize={54}
              fontWeight={600}
              color={t.fg}
              speed={speed}
            />
          </Sequence>
        </div>

        <div
          style={{
            position: "absolute",
            left: 0,
            top: 532,
            width: REF_W,
            height: 36,
          }}
        >
          <Sequence from={Math.round(SUB_START / speed)} layout="none">
            <BlurOutUp
              text={`Powered by ${count} sponsors`}
              fontSize={24}
              fontWeight={500}
              color={t.fgMuted}
              speed={speed}
            />
          </Sequence>
        </div>

        <div
          style={{
            position: "absolute",
            left: 0,
            top: 584,
            width: REF_W,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 12,
          }}
        >
          <div
            style={{
              translate: `0 ${ctaY}px`,
              opacity: ctaProgress,
              filter: `blur(${ctaBlur}px)`,
              display: "flex",
              alignItems: "center",
              gap: 10,
              padding: "14px 26px",
              borderRadius: 9999,
              background: accentColor,
              color: "#ffffff",
              fontSize: 24,
              fontWeight: 600,
              fontFamily: FONT_FAMILY,
              willChange: "transform, opacity, filter",
            }}
          >
            <HeartGlyph size={22} accent="#ffffff" draw={1} fill={1} />
            Become a sponsor
          </div>
          <div
            style={{
              opacity: accountOpacity * 0.9,
              fontSize: 18,
              fontWeight: 400,
              color: t.fgMuted,
              fontFamily: FONT_FAMILY,
            }}
          >
            github.com/sponsors/{account}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

