export function GitHubStars({
  repo = "remotion-dev/remotion",
  totalStars = 24813,
  stargazers = SAMPLE_STARGAZERS,
  orientation = "horizontal",
  accentColor = "#ffbb00",
  speed = 1,
  theme = "light",
  repoAvatarUrl,
}: GitHubStarsProps) {
  const frame = useCurrentFrame();
  const { durationInFrames, width, height } = useVideoConfig();
  const t = THEMES[theme] ?? THEMES.light;
  const isVertical = orientation === "vertical";

  // Render at the native reference size for the orientation, then scale to fit
  // the actual canvas — keeps proportions at any resolution and letterboxes a
  // vertical layout cleanly inside a horizontal preview canvas.
  const refW = isVertical ? 720 : 1280;
  const refH = isVertical ? 1280 : 720;
  const stageScale = Math.min(width / refW, height / refH);

  const rows = useMemo(() => downsampleStargazers(stargazers), [stargazers]);
  const N = rows.length;

  // Progress drivers: monotonic counter ramp + non-monotonic elastic scroll.
  const counterProgress = computeCounterProgress({
    frame,
    speed,
    durationInFrames,
  });
  const pScroll = computeScrollProgress({ frame, speed, durationInFrames });
  const p = Math.max(0, Math.min(1, (frame * speed) / durationInFrames));

  const current = counterProgress * totalStars;

  // List viewport geometry (in reference px).
  const rowH = isVertical ? 96 : 88;
  const avatarSize = isVertical ? 60 : 56;
  const loginSize = isVertical ? 30 : 28;
  const dateFormat = isVertical ? "MMM yyyy" : "MMM d, yyyy";
  const formattedRows = useMemo(
    () =>
      rows.map((sg) => {
        try {
          return { sg, dateLabel: format(parseISO(sg.starredAt), dateFormat) };
        } catch {
          return { sg, dateLabel: sg.starredAt };
        }
      }),
    [rows, dateFormat],
  );

  const viewport = isVertical
    ? { x: 48, y: 320, w: 624, h: 888, radius: 28 }
    : { x: 560, y: 60, w: 640, h: 600, radius: 24 };

  const visibleRows = Math.floor(viewport.h / rowH);
  const D = Math.max(0, (N - visibleRows + 1) * rowH);
  const scrollY = -pScroll * D;

  const spacerRows = computeSpacerRows({
    N,
    rowH,
    viewportH: viewport.h,
    visibleRows,
  });
  const spacerPx = spacerRows * rowH;

  const settle = interpolate(p, [0.92, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Counter zone type scale.
  const counterSize = isVertical ? 96 : 120;
  const starSize = isVertical ? 56 : 64;
  const underlineMax = isVertical ? 200 : 240;
  const underlineWidth = counterProgress * underlineMax;

  const fadeH = Math.round(viewport.h * 0.12);

  const listViewport = (
    <div
      style={{
        position: "absolute",
        left: viewport.x,
        top: viewport.y,
        width: viewport.w,
        height: viewport.h,
        overflow: "hidden",
        borderRadius: viewport.radius,
        border: `1px solid ${t.border}`,
        background: t.bg,
      }}
    >
      <div
        style={{
          translate: `0 ${scrollY}px`,
          willChange: "transform",
        }}
      >
        {formattedRows.map(({ sg, dateLabel }, i) => (
          <Row
            key={`${sg.login}-${i}`}
            stargazer={sg}
            index={i}
            rowH={rowH}
            avatarSize={avatarSize}
            loginSize={loginSize}
            dateLabel={dateLabel}
            accent={accentColor}
            theme={t}
            isActive={i === N - 1}
            settle={i === N - 1 ? settle : 0}
            showSeparator={i < N - 1}
            opacity={1}
          />
        ))}
        {spacerPx > 0 && (
          <div style={{ height: spacerPx }} aria-hidden="true" />
        )}
      </div>
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: fadeH,
          background: `linear-gradient(to bottom, ${t.bg}, transparent)`,
          pointerEvents: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          right: 0,
          height: fadeH,
          background: `linear-gradient(to top, ${t.bg}, transparent)`,
          pointerEvents: "none",
        }}
      />
    </div>
  );

  const underline = (
    <div
      style={{
        height: 4,
        width: underlineWidth,
        background: accentColor,
        borderRadius: 2,
      }}
    />
  );

  const repoOwner = repo.split("/")[0] || repo;
  const repoAvatarSize = isVertical ? 28 : 32;
  const repoAvatarSrc =
    repoAvatarUrl ?? `https://unavatar.io/github/${repoOwner}`;

  const repoSlug = (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 12,
        maxWidth: isVertical ? 600 : 392,
      }}
    >
      <Avatar
        login={repoOwner}
        avatarUrl={repoAvatarSrc}
        size={repoAvatarSize}
        theme={t}
      />
      <div
        style={{
          fontSize: isVertical ? 20 : 24,
          fontWeight: 500,
          color: t.fgMuted,
          fontFamily: FONT_FAMILY,
          overflow: "hidden",
          textOverflow: "ellipsis",
          whiteSpace: "nowrap",
        }}
      >
        {repo}
      </div>
    </div>
  );

  const counterZone = isVertical ? (
    <div
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        width: refW,
        height: 300,
        paddingTop: 72,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 14,
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 20 }}>
        <StarGlyph size={starSize} fill={accentColor} />
        <Odometer current={current} fontSize={counterSize} color={t.fg} />
      </div>
      {underline}
      {repoSlug}
    </div>
  ) : (
    <div
      style={{
        position: "absolute",
        left: 80,
        top: 0,
        width: 392,
        height: refH,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "flex-start",
      }}
    >
      <StarGlyph size={starSize} fill={accentColor} />
      <div style={{ height: 20 }} />
      <Odometer current={current} fontSize={counterSize} color={t.fg} />
      <div style={{ height: 16 }} />
      {underline}
      <div style={{ height: 20 }} />

      {repoSlug}
    </div>
  );

  return (
    <AbsoluteFill style={{ background: t.bg }}>
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: refW,
          height: refH,
          translate: "-50% -50%",
          scale: `${stageScale}`,
        }}
      >
        {counterZone}
        {listViewport}
      </div>
    </AbsoluteFill>
  );
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill, random } from "remotion";
import {
  makeCanvasPresentation,
  makeSceneShader,
} from "@/lib/remocn/canvas-presentation";

export type GlitchCutProps = {
  intensity?: number;
  slices?: number;
  rgbSplit?: number;
  blockNoise?: number;
};

const DEFAULTS = {
  intensity: 1,
  slices: 24,
  rgbSplit: 1,
  blockNoise: 0.6,
};

const STEPS = 22;

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_from;
uniform sampler2D u_to;
uniform float u_progress;
uniform float u_intensity;
uniform float u_slices;
uniform float u_rgb_split;
uniform float u_block_noise;

in vec2 v_uv;
out vec4 outColor;

const float PI = 3.141592653589793;
const float STEPS = ${STEPS}.0;
const float BLOCK_COLUMNS = 16.0;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

vec4 sampleSplit(sampler2D tex, vec2 uv, float split) {
  vec4 center = texture(tex, uv);
  float r = texture(tex, vec2(uv.x + split, uv.y)).r;
  float b = texture(tex, vec2(uv.x - split, uv.y)).b;
  return vec4(r, center.g, b, center.a);
}

void main() {
  float energy = pow(max(sin(u_progress * PI), 0.0), 0.7);
  float clock = floor(u_progress * STEPS);

  float row = floor(v_uv.y * u_slices);
  float torn = step(0.45, hash(vec2(row, clock)));
  float amount = hash(vec2(row + 17.0, clock * 1.7 + 3.0)) - 0.5;
  float sliceShift = amount * 0.3 * u_intensity * energy * torn;

  vec2 block = vec2(floor(v_uv.x * BLOCK_COLUMNS), row);
  float corrupt = step(
    1.0 - u_block_noise * 0.5 * energy,
    hash(block + clock * 7.3)
  );
  float blockShift =
    (hash(block + clock * 3.1 + 5.0) - 0.5) * 0.2 * u_intensity * corrupt;

  vec2 uv = vec2(fract(v_uv.x + sliceShift + blockShift), v_uv.y);
  float split = u_rgb_split * 0.018 * energy * (0.35 + abs(amount));

  float cut = 0.5 + (hash(vec2(row, 91.0)) - 0.5) * 0.32;
  float handed = step(cut, u_progress);

  vec4 from = sampleSplit(u_from, uv, split);
  vec4 to = sampleSplit(u_to, uv, split);
  vec4 color = mix(from, to, handed);
  vec4 leaked = mix(to, from, handed);

  float leak = corrupt * step(0.55, hash(block + clock * 11.0 + 13.0));
  color = mix(color, leaked, leak * 0.8);

  color.rgb +=
    vec3(0.05, 0.015, 0.09) *
    energy *
    torn *
    hash(vec2(row, clock + 41.0)) *
    color.a;

  outColor = color;
}`;

const shader = makeSceneShader<GlitchCutProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const {
      intensity = DEFAULTS.intensity,
      slices = DEFAULTS.slices,
      rgbSplit = DEFAULTS.rgbSplit,
      blockNoise = DEFAULTS.blockNoise,
    } = passedProps;
    gl.uniform1f(uniform("u_intensity"), intensity);
    gl.uniform1f(uniform("u_slices"), slices);
    gl.uniform1f(uniform("u_rgb_split"), rgbSplit);
    gl.uniform1f(uniform("u_block_noise"), blockNoise);
  },
);

const bandCut = (band: number) =>
  0.5 + (random(`glitch-cut-handoff-${band}`) - 0.5) * 0.32;

const GlitchCutFallback: React.FC<
  TransitionPresentationComponentProps<GlitchCutProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const {
    intensity = DEFAULTS.intensity,
    slices = DEFAULTS.slices,
    rgbSplit = DEFAULTS.rgbSplit,
  } = passedProps;
  const entering = presentationDirection === "entering";
  const p = presentationProgress;
  const energy = Math.max(0, Math.sin(p * Math.PI)) ** 0.7;

  if (energy < 0.002) {
    const settled = entering ? (p >= 0.5 ? 1 : 0) : p < 0.5 ? 1 : 0;
    return <AbsoluteFill style={{ opacity: settled }}>{children}</AbsoluteFill>;
  }

  const clock = Math.floor(p * STEPS);
  const bands = Math.max(2, Math.min(6, Math.round(slices / 5)));
  const height = 100 / bands;

  return (
    <AbsoluteFill>
      {Array.from({ length: bands }, (_, band) => {
        const shown = p >= bandCut(band) ? entering : !entering;
        if (!shown) {
          return null;
        }
        const shift =
          (random(`glitch-cut-shift-${clock}-${band}`) - 0.5) *
          52 *
          intensity *
          energy;
        const tint = band % 2 === 0 ? "rgb(255, 42, 90)" : "rgb(0, 224, 255)";
        const tintOpacity =
          rgbSplit * 0.2 * energy * random(`glitch-cut-tint-${clock}-${band}`);
        return (
          <AbsoluteFill
            key={band}
            style={{
              clipPath: `inset(${band * height}% 0 ${100 - (band + 1) * height}% 0)`,
              translate: `${shift}px`,
            }}
          >
            {children}
            <AbsoluteFill
              style={{
                background: tint,
                mixBlendMode: "screen",
                opacity: tintOpacity,
              }}
            />
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

const presentation = makeCanvasPresentation<GlitchCutProps>({
  shader,
  fallback: GlitchCutFallback,
});

export function glitchCut(
  props: GlitchCutProps = {},
): TransitionPresentation<GlitchCutProps> {
  return presentation(props);
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";
import {
  ShaderGrainGradient,
  type ShaderGrainGradientProps,
} from "@/components/remocn/shader-grain-gradient";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

const DEFAULT_COLORS = ["#3a3a52", "#4a4a68", "#8f88ae"];

export type GrainDissolveProps = {
  colors?: string[];
  colorBack?: string;
  shape?: NonNullable<ShaderGrainGradientProps["shape"]>;
  noise?: number;
  zoom?: number;
  speed?: number;
};

const GrainDissolvePresentation: React.FC<
  TransitionPresentationComponentProps<GrainDissolveProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const {
    colors = DEFAULT_COLORS,
    colorBack = "#141318",
    shape = "blob",
    noise = 0.3,
    zoom = 2,
    speed = 1,
  } = passedProps;
  const entering = presentationDirection === "entering";
  const p = presentationProgress;

  if (!entering) {
    const exitStyle: React.CSSProperties = {
      opacity: interpolate(p, [0.14, 0.34], [1, 0], clampOpts),
      filter: `blur(${interpolate(p, [0.06, 0.34], [0, 10], clampOpts)}px)`,
    };
    return <AbsoluteFill style={exitStyle}>{children}</AbsoluteFill>;
  }

  const fieldOpacity = interpolate(p, [0, 0.26], [0, 1], {
    ...clampOpts,
    easing: Easing.bezier(0.42, 0, 0.58, 1),
  });
  const intensity = interpolate(p, [0.08, 0.92], [0, 1], {
    ...clampOpts,
    easing: Easing.bezier(0.42, 0, 0.58, 1),
  });
  const softness = interpolate(p, [0.08, 0.92], [0, 1], {
    ...clampOpts,
    easing: Easing.bezier(0.42, 0, 0.58, 1),
  });
  const fieldScale = zoom * interpolate(p, [0, 1], [0.9, 1.15], clampOpts);

  const childStyle: React.CSSProperties = {
    opacity: interpolate(p, [0.7, 0.86], [0, 1], clampOpts),
    scale: `${interpolate(p, [0.7, 1], [1.05, 1], {
      ...clampOpts,
      easing: Easing.out(Easing.cubic),
    })})`,
    filter: `blur(${interpolate(p, [0.7, 0.92], [10, 0], clampOpts)}px)`,
  };

  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ opacity: fieldOpacity, pointerEvents: "none" }}>
        <ShaderGrainGradient
          speed={speed}
          colors={colors}
          colorBack={colorBack}
          shape={shape}
          noise={noise}
          intensity={intensity}
          softness={softness}
          scale={fieldScale}
        />
      </AbsoluteFill>
      <AbsoluteFill style={childStyle}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

export function grainDissolve(
  props: GrainDissolveProps = {},
): TransitionPresentation<GrainDissolveProps> {
  return {
    component: GrainDissolvePresentation,
    props,
  };
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill } from "remotion";
import {
  makeCanvasPresentation,
  makeSceneShader,
} from "@/lib/remocn/canvas-presentation";

export type GridWaveDirection = "ripple" | "left" | "right" | "up" | "down";

export type GridWaveProps = {
  tileSize?: number;
  waveWidth?: number;
  lift?: number;
  gap?: number;
  tint?: string;
  direction?: GridWaveDirection;
};

const DEFAULTS = {
  tileSize: 90,
  waveWidth: 0.16,
  lift: 2,
  gap: 0.12,
  tint: "#8fb4ff",
  direction: "ripple" as GridWaveDirection,
};

const AXES: Record<GridWaveDirection, [number, number]> = {
  ripple: [0, 0],
  left: [1, 0],
  right: [-1, 0],
  up: [0, -1],
  down: [0, 1],
};

function hexToRgb(hex: string): [number, number, number] {
  const value = hex.replace("#", "");
  const full =
    value.length === 3
      ? value
          .split("")
          .map((c) => c + c)
          .join("")
      : value;
  const int = Number.parseInt(full, 16);
  if (Number.isNaN(int)) {
    return [0.56, 0.71, 1];
  }
  return [
    ((int >> 16) & 255) / 255,
    ((int >> 8) & 255) / 255,
    (int & 255) / 255,
  ];
}

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_from;
uniform sampler2D u_to;
uniform float u_progress;
uniform float u_aspect;
uniform vec2 u_grid;
uniform float u_wave;
uniform float u_lift;
uniform float u_gap;
uniform vec3 u_tint;
uniform vec2 u_dir;
uniform float u_radial;

in vec2 v_uv;
out vec4 outColor;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float waveCoord(vec2 p) {
  vec2 off = (p - 0.5) * vec2(u_aspect, 1.0);
  float ring = length(off) / (0.5 * sqrt(u_aspect * u_aspect + 1.0));
  float sweep = clamp(dot(p - 0.5, u_dir) + 0.5, 0.0, 1.0);
  return mix(sweep, ring, u_radial);
}

void main() {
  float front = u_progress * (1.0 + 6.0 * u_wave) - 3.0 * u_wave;

  float selfPass =
    smoothstep(-u_wave * 0.4, u_wave * 0.4, front - waveCoord(v_uv));
  vec4 base = mix(texture(u_from, v_uv), texture(u_to, v_uv), selfPass);

  float edge = 0.5 - u_gap * 0.5;
  vec2 anchor = floor(v_uv * u_grid);

  vec4 face = vec4(0.0);
  float depth = -1.0;

  for (int oy = -1; oy <= 1; oy++) {
    for (int ox = -1; ox <= 1; ox++) {
      vec2 cell = anchor + vec2(float(ox), float(oy));
      vec2 centre = (cell + 0.5) / u_grid;

      float stagger = (hash(cell) - 0.5) * u_wave * 0.4;
      float w = front - waveCoord(centre) + stagger;
      float band = w / u_wave;
      float pulse = exp(-band * band);
      if (pulse <= depth) {
        continue;
      }

      float rise = pulse * u_lift;
      vec2 lean = centre - 0.5;
      lean = lean / max(length(lean), 0.0001) * rise * 0.15;
      float grow = 1.0 + rise * 0.5;

      vec2 q = (v_uv - centre) * u_grid;
      vec2 top = (q - lean) / grow;
      float onTop = max(abs(top.x), abs(top.y));
      float onFoot = max(abs(q.x), abs(q.y));
      bool lit = onTop <= edge;
      if (!lit && onFoot > edge) {
        continue;
      }
      depth = pulse;

      float pass = smoothstep(-u_wave * 0.4, u_wave * 0.4, w);
      vec2 local = lit ? top : clamp(top, -edge, edge);
      vec2 src = centre + local / u_grid;
      vec4 col = mix(texture(u_from, src), texture(u_to, src), pass);

      if (lit) {
        col.rgb = mix(col.rgb, u_tint, pulse * 0.12);
        col.rgb *= 1.0 + pulse * 0.06;
      } else {
        col.rgb = mix(col.rgb, u_tint, pulse * 0.06);
        col.rgb *= 1.0 - pulse * 0.24;
      }

      face = col;
    }
  }

  outColor = face + base * (1.0 - face.a);
}`;

const shader = makeSceneShader<GridWaveProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, width, height, passedProps }) => {
    const {
      tileSize = DEFAULTS.tileSize,
      waveWidth = DEFAULTS.waveWidth,
      lift = DEFAULTS.lift,
      gap = DEFAULTS.gap,
      tint = DEFAULTS.tint,
      direction = DEFAULTS.direction,
    } = passedProps;
    const size = Math.max(tileSize, 8);
    const axis = AXES[direction] ?? AXES[DEFAULTS.direction];
    const rgb = hexToRgb(tint);
    gl.uniform2f(
      uniform("u_grid"),
      Math.max(Math.round(width / size), 2),
      Math.max(Math.round(height / size), 2),
    );
    gl.uniform1f(uniform("u_wave"), Math.max(waveWidth, 0.02));
    gl.uniform1f(uniform("u_lift"), Math.max(lift, 0) * 0.35);
    gl.uniform1f(uniform("u_gap"), Math.min(Math.max(gap, 0), 0.45));
    gl.uniform3f(uniform("u_tint"), rgb[0], rgb[1], rgb[2]);
    gl.uniform2f(uniform("u_dir"), axis[0], axis[1]);
    gl.uniform1f(uniform("u_radial"), direction === "ripple" ? 1 : 0);
  },
);

const GridWaveFallback: React.FC<
  TransitionPresentationComponentProps<GridWaveProps>
> = ({ children, presentationProgress, presentationDirection }) => {
  const p = presentationProgress;

  if (presentationDirection === "exiting") {
    return <AbsoluteFill>{children}</AbsoluteFill>;
  }

  const reveal = Math.min(1, Math.max(0, (p - 0.2) / 0.6));

  return (
    <AbsoluteFill
      style={{
        opacity: reveal,
        scale: `${1.04 - reveal * 0.04}`,
      }}
    >
      {children}
    </AbsoluteFill>
  );
};

const presentation = makeCanvasPresentation<GridWaveProps>({
  shader,
  fallback: GridWaveFallback,
});

export function gridWave(
  props: GridWaveProps = {},
): TransitionPresentation<GridWaveProps> {
  return presentation(props);
}

"use client";

import type React from "react";
import { AbsoluteFill, useVideoConfig } from "remotion";
import {
  type CanvasFilterProps,
  makeCanvasFilter,
  makeFilterShader,
} from "@/lib/remocn/canvas-presentation";

export type HalftonePrintProps = {
  dotSize?: number;
  angle?: number;
  misregistration?: number;
  paperTint?: string;
};

const DEFAULTS = {
  dotSize: 10,
  angle: 0,
  misregistration: 1.2,
  paperTint: "#f4efe4",
};

type NormalizedProps = {
  cell: number;
  angle: number;
  shift: number;
  paper: string;
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_aspect;
uniform float u_cell;
uniform float u_angle;
uniform float u_shift;
uniform vec3 u_paper;

in vec2 v_uv;
out vec4 outColor;

const vec3 CYAN_ABSORB = vec3(0.92, 0.12, 0.02);
const vec3 MAGENTA_ABSORB = vec3(0.10, 0.88, 0.06);
const vec3 YELLOW_ABSORB = vec3(0.03, 0.10, 0.90);

vec2 toSquare(vec2 uv) {
  return vec2(uv.x * u_aspect, uv.y);
}

vec2 fromSquare(vec2 p) {
  return vec2(p.x / u_aspect, p.y);
}

float screenInk(float angle, vec2 drift, vec3 pick) {
  vec2 p = toSquare(v_uv);
  float s = sin(angle);
  float c = cos(angle);
  vec2 r = vec2(p.x * c - p.y * s, p.x * s + p.y * c);

  vec2 center = (floor(r / u_cell) + 0.5) * u_cell;
  vec2 unrotated =
    vec2(center.x * c + center.y * s, -center.x * s + center.y * c);

  vec4 texel = texture(u_scene, fromSquare(unrotated + drift));
  vec3 straight = texel.rgb / max(texel.a, 0.004);
  float ink = clamp(1.0 - dot(straight, pick), 0.0, 1.0) * texel.a;

  float radius = sqrt(ink) * u_cell * 0.72;
  float aa = u_cell * 0.045;
  float coverage = 1.0 - smoothstep(radius - aa, radius + aa, length(r - center));
  return coverage * step(0.002, ink);
}

void main() {
  vec4 source = texture(u_scene, v_uv);

  float cyan =
    screenInk(u_angle + 0.2618, u_shift * vec2(1.0, 0.0), vec3(1.0, 0.0, 0.0));
  float magenta =
    screenInk(u_angle + 1.3090, u_shift * vec2(-0.5, 0.866), vec3(0.0, 1.0, 0.0));
  float yellow =
    screenInk(u_angle, u_shift * vec2(-0.5, -0.866), vec3(0.0, 0.0, 1.0));

  vec3 color = u_paper;
  color *= 1.0 - cyan * CYAN_ABSORB;
  color *= 1.0 - magenta * MAGENTA_ABSORB;
  color *= 1.0 - yellow * YELLOW_ABSORB;

  outColor = vec4(color * source.a, source.a);
}`;

function toRgb(hex: string): [number, number, number] {
  const value = hex.replace("#", "");
  const full =
    value.length === 3
      ? value
          .split("")
          .map((c) => c + c)
          .join("")
      : value;
  const int = Number.parseInt(full, 16);
  if (Number.isNaN(int)) return [1, 1, 1];
  return [
    ((int >> 16) & 255) / 255,
    ((int >> 8) & 255) / 255,
    (int & 255) / 255,
  ];
}

const shader = makeFilterShader<NormalizedProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const { cell, angle, shift, paper } = passedProps;
    gl.uniform1f(uniform("u_cell"), cell);
    gl.uniform1f(uniform("u_angle"), angle);
    gl.uniform1f(uniform("u_shift"), shift);
    gl.uniform3fv(uniform("u_paper"), toRgb(paper));
  },
);

const HalftonePrintFallback: React.FC<NormalizedProps & CanvasFilterProps> = ({
  children,
}) => <AbsoluteFill>{children}</AbsoluteFill>;

const HalftonePrintCanvas = makeCanvasFilter<NormalizedProps>({
  shader,
  fallback: HalftonePrintFallback,
});

export const HalftonePrint: React.FC<
  HalftonePrintProps & CanvasFilterProps
> = ({
  dotSize = DEFAULTS.dotSize,
  angle = DEFAULTS.angle,
  misregistration = DEFAULTS.misregistration,
  paperTint = DEFAULTS.paperTint,
  children,
}) => {
  const { height } = useVideoConfig();

  return (
    <HalftonePrintCanvas
      cell={Math.max(dotSize, 1) / height}
      angle={(angle * Math.PI) / 180}
      shift={misregistration / height}
      paper={paperTint}
    >
      {children}
    </HalftonePrintCanvas>
  );
};

"use client";

import type React from "react";
import { AbsoluteFill } from "remotion";
import {
  type CanvasFilterProps,
  makeCanvasFilter,
  makeFilterShader,
} from "@/lib/remocn/canvas-presentation";

export type HologramProps = {
  tint?: string;
  glow?: number;
  ghost?: number;
  flicker?: number;
  intensity?: number;
};

const DEFAULTS = {
  tint: "#63e8ff",
  glow: 1,
  ghost: 1,
  flicker: 1,
  intensity: 1,
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_aspect;
uniform float u_frame;
uniform vec3 u_tint;
uniform float u_glow;
uniform float u_ghost;
uniform float u_flicker;
uniform float u_intensity;

in vec2 v_uv;
out vec4 outColor;

const float PI = 3.141592653589793;
const float TAU = 6.28318530718;
const float GOLDEN = 2.39996323;
const int HALO_TAPS = 8;
const vec3 LUMA = vec3(0.299, 0.587, 0.114);

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453123);
}

float lumaAt(vec2 uv) {
  return dot(texture(u_scene, uv).rgb, LUMA);
}

void main() {
  vec4 src = texture(u_scene, v_uv);
  float amount = clamp(u_intensity, 0.0, 1.0);

  if (!(amount > 0.001)) {
    outColor = src;
    return;
  }

  float row = floor(v_uv.y * 300.0);
  float clock = floor(u_frame);
  float slip =
    (hash(vec2(row, clock)) - 0.5) * u_ghost * 0.006 * step(0.55, hash(vec2(row, clock + 3.0)));
  vec2 base = vec2(v_uv.x + slip / u_aspect, v_uv.y);

  vec4 held = texture(u_scene, base);
  float lit = dot(held.rgb, LUMA);

  vec2 apart = vec2(u_ghost * 0.0045 / u_aspect, u_ghost * 0.0035);
  vec3 twin = texture(u_scene, base + apart).rgb;

  float step2 = 0.0022;
  float gx =
    lumaAt(base + vec2(step2 / u_aspect, 0.0)) -
    lumaAt(base - vec2(step2 / u_aspect, 0.0));
  float gy = lumaAt(base + vec2(0.0, step2)) - lumaAt(base - vec2(0.0, step2));
  float rim = clamp(length(vec2(gx, gy)) * 7.0, 0.0, 1.0);

  vec3 halo = vec3(0.0);
  for (int i = 0; i < HALO_TAPS; i++) {
    float angle = float(i) * GOLDEN;
    float reach = sqrt((float(i) + 0.5) / float(HALO_TAPS)) * u_glow * 0.022;
    vec2 at = base + vec2(cos(angle) * reach / u_aspect, sin(angle) * reach);
    halo += max(texture(u_scene, at).rgb - 0.34, vec3(0.0));
  }
  halo /= float(HALO_TAPS);

  vec3 core = u_tint * (0.12 + lit * 1.55);
  core = mix(core, held.rgb * u_tint * 1.9, 0.12);
  core += u_tint * rim * 1.9 * u_glow;
  core += halo * u_tint * 2.4 * u_glow;
  core += twin * u_tint * 0.5 * u_ghost;

  float interlace = mod(row, 2.0) < 1.0 ? 1.0 : 0.58;
  core *= interlace;

  float blink =
    1.0 -
    u_flicker *
      (0.04 + 0.05 * hash(vec2(clock, 7.0))) *
      (0.5 + 0.5 * sin(u_frame * TAU / 15.0));
  core *= blink;

  float presence = clamp(lit * 1.5 + rim * 0.8 + 0.03, 0.0, 1.0);
  vec3 painted = clamp(u_tint * 0.035 + core * presence, 0.0, 1.0);

  outColor = vec4(mix(src.rgb, painted, amount), src.a);
}`;

function toRgb(hex: string): [number, number, number] {
  const value = hex.replace("#", "");
  const full =
    value.length === 3
      ? value
          .split("")
          .map((c) => c + c)
          .join("")
      : value;
  const int = Number.parseInt(full, 16);
  if (Number.isNaN(int)) return [1, 1, 1];
  return [
    ((int >> 16) & 255) / 255,
    ((int >> 8) & 255) / 255,
    (int & 255) / 255,
  ];
}

const shader = makeFilterShader<HologramProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const {
      tint = DEFAULTS.tint,
      glow = DEFAULTS.glow,
      ghost = DEFAULTS.ghost,
      flicker = DEFAULTS.flicker,
      intensity = DEFAULTS.intensity,
    } = passedProps;
    gl.uniform3fv(uniform("u_tint"), toRgb(tint));
    gl.uniform1f(uniform("u_glow"), glow);
    gl.uniform1f(uniform("u_ghost"), ghost);
    gl.uniform1f(uniform("u_flicker"), flicker);
    gl.uniform1f(uniform("u_intensity"), intensity);
  },
);

const HologramFallback: React.FC<HologramProps & CanvasFilterProps> = ({
  children,
  tint = DEFAULTS.tint,
  intensity = DEFAULTS.intensity,
}) => (
  <AbsoluteFill>
    <AbsoluteFill style={{ filter: `saturate(${1 - 0.5 * intensity})` }}>
      {children}
    </AbsoluteFill>
    <AbsoluteFill
      style={{
        background: tint,
        mixBlendMode: "color",
        opacity: 0.75 * intensity,
      }}
    />
    <AbsoluteFill
      style={{
        background:
          "repeating-linear-gradient(to bottom, rgba(0, 0, 0, 0.32) 0px, rgba(0, 0, 0, 0.32) 2px, transparent 2px, transparent 4px)",
        opacity: intensity,
      }}
    />
  </AbsoluteFill>
);

export const Hologram = makeCanvasFilter<HologramProps>({
  shader,
  fallback: HologramFallback,
});

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill, Easing, interpolate, random } from "remotion";

// ===========================================================================
// icon-scatter — a scene change made of icons.
//
// The outgoing scene shatters into a deterministic field of line-icons that
// draw themselves on, spin, and scatter outward; at mid-transition the field
// is densest and covers the swap; then the icons fly off and draw away as the
// incoming scene resolves through them. Motion-forward and self-contained —
// the paths are inlined, the draw-on is CSS `pathLength` only, so the
// transition ships as one file with no icon dependencies.
//
// Pace it with `linearTiming`/`springTiming` like any presentation. Reads
// best over ~16–26 frames.
// ===========================================================================

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

// Single-path Lucide-style glyphs (viewBox 0 0 24 24) — each draws cleanly
// from one continuous stroke via a normalized dashoffset.
const ICON_PATHS: string[] = [
  // star
