import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

export type PushThroughProps = {
  zoom?: number;
  blur?: number;
};

const PushThroughPresentation: React.FC<
  TransitionPresentationComponentProps<PushThroughProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const { zoom = 2.4, blur = 14 } = passedProps;
  const entering = presentationDirection === "entering";
  const p = presentationProgress;

  if (!entering) {
    const exitStyle: React.CSSProperties = {
      opacity: interpolate(p, [0.4, 0.62], [1, 0], {
        ...clampOpts,
        easing: Easing.bezier(0.42, 0, 0.58, 1),
      }),
      scale: `${interpolate(p, [0, 0.65], [1, zoom], {
        ...clampOpts,
        easing: Easing.in(Easing.cubic),
      })}`,
      filter: `blur(${interpolate(p, [0.15, 0.6], [0, blur], clampOpts)}px)`,
    };
    return <AbsoluteFill style={exitStyle}>{children}</AbsoluteFill>;
  }

  const childStyle: React.CSSProperties = {
    opacity: interpolate(p, [0.3, 0.5], [0, 1], clampOpts),
    scale: `${interpolate(p, [0.3, 0.88, 1], [0.68, 1.02, 1], {
      ...clampOpts,
      easing: Easing.out(Easing.cubic),
    })}`,
    filter: `blur(${interpolate(p, [0.3, 0.75], [blur * 0.7, 0], clampOpts)}px)`,
  };

  return <AbsoluteFill style={childStyle}>{children}</AbsoluteFill>;
};

export function pushThrough(
  props: PushThroughProps = {},
): TransitionPresentation<PushThroughProps> {
  return {
    component: PushThroughPresentation,
    props,
  };
}

"use client";

import {
  Easing,
  interpolateColors,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export interface RadialBurstProps {
  /** Number of rounded segments, from 4 to 16. */
  segments?: number;
  /** Burst radius at a 720px reference size. */
  radius?: number;
  /** Segment thickness at a 720px reference size. */
  thickness?: number;
  /** Rotation during assembly, in degrees; negative reverses it. */
  rotation?: number;
  /** Sculptural stretch and tilt, from 0 (classic) to 1.5. */
  intensity?: number;
  /** Curvature of the flying ribbons in degrees. */
  twist?: number;
  /** Number of contour echoes, from 0 to 5. */
  echoes?: number;
  color?: string;
  accentColor?: string;
  backgroundColor?: string;
  speed?: number;
  loop?: boolean;
  className?: string;
}

/** The ring has completely left the composition by this frame at 30 fps. */
export const radialBurstLength = 114;
const CYCLE = 120;
const finite = (value: number, fallback: number) =>
  Number.isFinite(value) ? value : fallback;
const clamp = (value: number) => Math.min(1, Math.max(0, value));
const mix = (from: number, to: number, progress: number) =>
  from + (to - from) * progress;
const easeInOut = Easing.bezier(0.65, 0, 0.25, 1);
const easeOut = Easing.bezier(0.16, 1, 0.3, 1);
const progress = (frame: number, start: number, end: number) =>
  clamp((frame - start) / (end - start));

/** Includes the clean tail, in frames at 30 fps. */
export function getRadialBurstDuration({
  speed = 1,
}: Pick<RadialBurstProps, "speed"> = {}) {
  const rate = finite(speed, 1);
  return rate <= 0 ? 1 : Math.max(1, Math.ceil(CYCLE / rate));
}

export function getRadialBurstState(
  frame: number,
  {
    segments = 8,
    radius = 210,
    thickness = 30,
    rotation = 135,
    intensity = 1,
    loop = false,
    width = 1280,
    height = 720,
  }: Omit<
    RadialBurstProps,
    "color" | "accentColor" | "backgroundColor" | "speed" | "className"
  > & {
    width?: number;
    height?: number;
  } = {},
) {
  const w = Math.max(1, finite(width, 1280));
  const h = Math.max(1, finite(height, 720));
  const unit = Math.min(w, h) / 720;
  const time = Math.max(0, finite(frame, 0));
  const local = loop ? time % CYCLE : time;
  const count = Math.round(Math.min(16, Math.max(4, finite(segments, 8))));
  const burstRadius = Math.min(280, Math.max(100, finite(radius, 210))) * unit;
  const stroke = Math.min(60, Math.max(8, finite(thickness, 30))) * unit;
  const ringRadius = burstRadius * 0.68;
  const assemble = easeInOut(progress(local, 44, 76));
  const curl = easeInOut(progress(local, 48, 78));
  const close = easeInOut(progress(local, 72, 84));
  const anticipate = easeInOut(progress(local, 86, 96));
  const exit = progress(local, 96, radialBurstLength) ** 2.6;
  const launch = spring({
    frame: Math.max(0, local - 18),
    fps: 30,
    durationInFrames: 26,
    config: { damping: 13, stiffness: 170, mass: 0.8 },
  });
  const pop = spring({
    frame: Math.max(0, local - 2),
    fps: 30,
    durationInFrames: 16,
    config: { damping: 11, stiffness: 180, mass: 0.65 },
  });
  const ringStroke = mix(stroke * 0.8, stroke * 1.1, anticipate);
  const exitStroke = mix(ringStroke, stroke * 2.2, exit);
  // The inner edge, not just the centerline, must pass every corner.
  const clearRadius = Math.hypot(w, h) / 2 + stroke * 2.2 + 2;
  const orbitRadius = mix(
    mix(28 * unit, burstRadius, launch),
    ringRadius,
    assemble,
  );
  const finalRadius = mix(ringRadius, ringRadius * 0.84, anticipate);
  const strength = Math.min(1.5, Math.max(0, finite(intensity, 1)));
  const energy = Math.sin(Math.PI * progress(local, 18, 84));
  const tilt =
    easeOut(progress(local, 18, 48)) *
    (1 - easeInOut(progress(local, 96, 114)));

  return {
    frame: local,
    count,
    unit,
    strength,
    energy: Math.max(0, energy) * strength,
    planeScale: 1 - tilt * 0.46 * Math.min(1.5, strength),
    planeAngle:
      Math.sin(progress(local, 18, 114) * Math.PI * 1.6) * 32 * strength,
    offsetX:
      Math.sin(Math.PI * progress(local, 18, 114)) * 65 * unit * strength,
    offsetY:
      -Math.sin(Math.PI * progress(local, 18, 114)) * 32 * unit * strength,
    dotRadius: 37 * unit * pop * (1 - easeOut(progress(local, 18, 26))),
    dotSquash: 1 - Math.sin(Math.PI * progress(local, 2, 18)) * 0.16,
    showSegments: local >= 18 && local < 84,
    showRing: local >= 84 && local < radialBurstLength,
    segmentOpacity: easeOut(progress(local, 18, 23)),
    radius: local < 84 ? orbitRadius : mix(finalRadius, clearRadius, exit),
    strokeWidth: local < 84 ? mix(stroke, stroke * 0.8, assemble) : exitStroke,
    segmentLength: mix(
      12 * unit,
      Math.min(82 * unit, burstRadius * 0.42),
      easeOut(progress(local, 18, 36)),
    ),
    curl,
    // Gaps close with a tiny overlap to prevent raster seams at the weld.
    arcAngle: ((Math.PI * 2) / count) * mix(0.62, 1.002, close),
    rotation: finite(rotation, 135) * easeInOut(progress(local, 34, 84)),
  };
}

/** A straight rounded spoke curls continuously into a circular arc. */
function getSegmentPoints({
  radius,
  segmentLength,
  arcAngle,
  curl,
}: Pick<
  ReturnType<typeof getRadialBurstState>,
  "radius" | "segmentLength" | "arcAngle" | "curl"
>) {
  const half = arcAngle / 2;
  const x = radius * Math.cos(half);
  const y = radius * Math.sin(half);
  const tangent = (4 / 3) * Math.tan(arcAngle / 4) * radius;
  const arc = [
    [x, -y],
    [x + tangent * Math.sin(half), -y + tangent * Math.cos(half)],
    [x + tangent * Math.sin(half), y - tangent * Math.cos(half)],
    [x, y],
  ];
  const angle = (curl * Math.PI) / 2;
  return [-0.5, -1 / 6, 1 / 6, 0.5].map((offset, index) => {
    const px = radius + segmentLength * offset * Math.cos(angle);
    const py = segmentLength * offset * Math.sin(angle);
    return [mix(px, arc[index][0], curl), mix(py, arc[index][1], curl)];
  });
}

export function getRadialBurstSegmentPath(
  state: Parameters<typeof getSegmentPoints>[0],
) {
  const points = getSegmentPoints(state).map((point) =>
    point.map((value) => value.toFixed(3)).join(" "),
  );
  return `M ${points[0]} C ${points[1]} ${points[2]} ${points[3]}`;
}

/** Sample a bent centerline and its normals to make a tapered, filled ribbon. */
export function getRadialBurstRibbonPath(
  state: ReturnType<typeof getRadialBurstState>,
  index: number,
  twist = 110,
) {
  const energy = state.energy;
  const points = getSegmentPoints({
    ...state,
    radius: state.radius * (1 + Math.sin(index * 2.4) * energy * 0.15),
    segmentLength: state.segmentLength * (1 + energy * 2.8),
  });
  const bend =
    (Math.min(180, Math.max(-180, finite(twist, 110))) / 110) *
    energy *
    145 *
    state.unit;
  points[1][1] += bend * 0.55;
  points[2][1] += bend;
  // Carry the tip with the bend so the centerline does not double back into
  // a hairpin while the ribbon transitions from a spoke to an arc.
  points[3][1] += bend * 1.25;
  points[2][0] += energy * 38 * state.unit;
  const upper: string[] = [];
  const lower: string[] = [];
  const format = (x: number, y: number) => `${x.toFixed(3)} ${y.toFixed(3)}`;
  let firstWidth = 0;
  let lastWidth = 0;
  for (let sample = 0; sample <= 36; sample++) {
    const t = sample / 36;
    const q = 1 - t;
    const x =
      q ** 3 * points[0][0] +
      3 * q * q * t * points[1][0] +
      3 * q * t * t * points[2][0] +
      t ** 3 * points[3][0];
    const y =
      q ** 3 * points[0][1] +
      3 * q * q * t * points[1][1] +
      3 * q * t * t * points[2][1] +
      t ** 3 * points[3][1];
    const dx =
      3 * q * q * (points[1][0] - points[0][0]) +
      6 * q * t * (points[2][0] - points[1][0]) +
      3 * t * t * (points[3][0] - points[2][0]);
    const dy =
      3 * q * q * (points[1][1] - points[0][1]) +
      6 * q * t * (points[2][1] - points[1][1]) +
      3 * t * t * (points[3][1] - points[2][1]);
    const length = Math.max(0.001, Math.hypot(dx, dy));
    const ddx =
      6 * q * (points[2][0] - 2 * points[1][0] + points[0][0]) +
      6 * t * (points[3][0] - 2 * points[2][0] + points[1][0]);
    const ddy =
      6 * q * (points[2][1] - 2 * points[1][1] + points[0][1]) +
      6 * t * (points[3][1] - 2 * points[2][1] + points[1][1]);
    const curvature = Math.abs(dx * ddy - dy * ddx) / length ** 3;
    const swell = Math.sin(Math.PI * t) ** 1.4;
    // Offset curves fold back on themselves when their width exceeds the
    // bend radius. Limit the width locally to keep tight curls smooth.
    const halfWidth = Math.min(
      (state.strokeWidth / 2) * (1 + energy * (2.4 * swell - 0.65 * t)),
      0.72 / Math.max(curvature, 0.00001),
    );
    if (sample === 0) firstWidth = halfWidth;
    if (sample === 36) lastWidth = halfWidth;
    upper.push(
      format(x - (dy / length) * halfWidth, y + (dx / length) * halfWidth),
    );
    lower.push(
      format(x + (dy / length) * halfWidth, y - (dx / length) * halfWidth),
    );
  }
  return `M ${upper.join(" L ")} A ${lastWidth} ${lastWidth} 0 0 0 ${lower[36]} L ${lower.slice(0, -1).reverse().join(" L ")} A ${firstWidth} ${firstWidth} 0 0 0 ${upper[0]} Z`;
}

export function RadialBurst({
  segments = 8,
  radius = 210,
  thickness = 30,
  rotation = 135,
  intensity = 1,
  twist = 110,
  echoes = 3,
  color = "#ffffff",
  accentColor = "#f4e4a7",
  backgroundColor = "#a800b7",
  speed = 1,
  loop = false,
  className,
}: RadialBurstProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const time = frame * (30 / fps) * Math.max(0, finite(speed, 1));
  const options = {
    segments,
    radius,
    thickness,
    rotation,
    intensity,
    loop,
    width,
    height,
  };
  const state = getRadialBurstState(time, options);
  const path = getRadialBurstSegmentPath(state);
  const echoCount = Math.round(Math.min(5, Math.max(0, finite(echoes, 3))));
  const plane = (pose: typeof state) =>
    `translate(${pose.offsetX} ${pose.offsetY}) rotate(${pose.planeAngle}) scale(1 ${pose.planeScale})`;
  const ribbons = (pose: typeof state, outline: boolean) =>
    Array.from({ length: pose.count }, (_, index) => (
      <path
        key={index}
        d={getRadialBurstRibbonPath(pose, index, twist)}
        transform={`rotate(${(index * 360) / pose.count + pose.rotation - 90 + Math.sin(index * 1.7) * pose.energy * 16})`}
        fill={
          outline
            ? "none"
            : index % 3 === 0
              ? interpolateColors(
                  clamp(pose.energy),
                  [0, 1],
                  [color, accentColor],
                )
              : color
        }
        stroke={outline ? color : "none"}
        strokeWidth={1.5 * pose.unit}
      />
    ));

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        backgroundColor,
      }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label="Geometric radial burst"
        style={{ display: "block" }}
      >
        <g transform={`translate(${width / 2} ${height / 2})`}>
          {state.strength > 0 &&
          state.frame >= 18 &&
          state.frame < radialBurstLength
            ? Array.from({ length: echoCount }, (_, index) => {
                const lag = (echoCount - index) * 2.2;
                const echo = getRadialBurstState(
                  Math.max(18, state.frame - lag),
                  { ...options, loop: false },
                );
                const opacity =
                  0.36 *
                  (1 - index / (echoCount + 1)) *
                  Math.min(1, state.strength) *
                  (1 - easeOut(progress(state.frame, 107, 114)));
                return (
                  <g key={index} transform={plane(echo)} opacity={opacity}>
                    {echo.showSegments ? (
                      ribbons(echo, true)
                    ) : echo.showRing ? (
                      <circle
                        r={echo.radius}
                        fill="none"
                        stroke={index % 2 ? color : accentColor}
                        strokeWidth={echo.strokeWidth * (0.22 + index * 0.07)}
                      />
                    ) : null}
                  </g>
                );
              })
            : null}
          <g transform={plane(state)}>
            {state.dotRadius > 0.001 ? (
              <circle
                r={state.dotRadius}
                fill={color}
                transform={`scale(${1 / state.dotSquash} ${state.dotSquash})`}
              />
            ) : null}
            {state.showSegments && state.strength > 0 ? (
              <g opacity={state.segmentOpacity}>{ribbons(state, false)}</g>
            ) : state.showSegments ? (
              <g
                fill="none"
                stroke={color}
                strokeWidth={state.strokeWidth}
                strokeLinecap="round"
                opacity={state.segmentOpacity}
                transform={`rotate(${state.rotation - 90})`}
              >
                {Array.from({ length: state.count }, (_, index) => (
                  <path
                    key={index}
                    d={path}
                    transform={`rotate(${(index * 360) / state.count})`}
                  />
                ))}
              </g>
            ) : null}
            {state.showRing ? (
              <circle
                r={state.radius}
                fill="none"
                stroke={color}
                strokeWidth={state.strokeWidth}
              />
            ) : null}
          </g>
        </g>
      </svg>
    </div>
  );
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";
import { ShaderGrainGradient } from "@/components/remocn/shader-grain-gradient";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

const DEFAULT_COLORS = ["#3a3a52", "#4a4a68", "#8f88ae"];

export type RippleZoomProps = {
  colors?: string[];
  colorBack?: string;
  intensity?: number;
  softness?: number;
  noise?: number;
  zoom?: number;
  speed?: number;
};

const RippleZoomPresentation: React.FC<
  TransitionPresentationComponentProps<RippleZoomProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const {
    colors = DEFAULT_COLORS,
    colorBack = "#141318",
    intensity = 0.5,
    softness = 0.5,
    noise = 0.5,
    zoom = 4,
    speed = 1,
  } = passedProps;
  const entering = presentationDirection === "entering";
  const p = presentationProgress;

  if (!entering) {
    const exitStyle: React.CSSProperties = {
      opacity: interpolate(p, [0.35, 0.55], [1, 0], {
        ...clampOpts,
        easing: Easing.bezier(0.42, 0, 0.58, 1),
      }),
      scale: `${interpolate(p, [0.3, 0.62], [1, 1.6], {
        ...clampOpts,
        easing: Easing.in(Easing.cubic),
      })}`,
    };
    return <AbsoluteFill style={exitStyle}>{children}</AbsoluteFill>;
  }

  const fieldOpacity = interpolate(p, [0.08, 0.32], [0, 1], {
    ...clampOpts,
    easing: Easing.bezier(0.42, 0, 0.58, 1),
  });
  const fieldScale = interpolate(p, [0.32, 1], [0.2, zoom], {
    ...clampOpts,
    easing: Easing.bezier(0.7, 0, 0.3, 1),
  });

  const childStyle: React.CSSProperties = {
    opacity: interpolate(p, [0.45, 0.62], [0, 1], clampOpts),
    scale: `${interpolate(p, [0.42, 0.97], [0.2, 1], {
      ...clampOpts,
      easing: Easing.bezier(0.33, 1, 0.68, 1),
    })}`,
    filter: `blur(${interpolate(p, [0.42, 0.8], [8, 0], clampOpts)}px)`,
  };

  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ opacity: fieldOpacity, pointerEvents: "none" }}>
        <ShaderGrainGradient
          speed={speed}
          shape="ripple"
          colors={colors}
          colorBack={colorBack}
          intensity={intensity}
          softness={softness}
          noise={noise}
          scale={fieldScale}
        />
      </AbsoluteFill>
      <AbsoluteFill style={childStyle}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

export function rippleZoom(
  props: RippleZoomProps = {},
): TransitionPresentation<RippleZoomProps> {
  return {
    component: RippleZoomPresentation,
    props,
  };
}

import { Easing, interpolate, random } from "remotion";

export const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

export const EXPO = Easing.bezier(0.16, 1, 0.3, 1);

export const FADE = Easing.out(Easing.quad);

export const SETTLE = Easing.spring({ damping: 18, stiffness: 120, mass: 1 });

export const SETTLE_SOFT = Easing.spring({
  damping: 26,
  stiffness: 90,
  mass: 1,
});

export const SETTLE_MARK = Easing.spring({
  damping: 13,
  stiffness: 140,
  mass: 1,
});

export const stagger = (
  index: number,
  base = 5,
  power = 0.8,
  jitter = 1.5,
  seed = "remocn-stagger",
): number =>
  Math.max(
    0,
    index ** power * base + (random(`${seed}-${index}`) - 0.5) * 2 * jitter,
  );

export const fadeIn = (frame: number, at: number, frames = 7): number =>
  interpolate(frame, [at, at + frames], [0, 1], { ...CLAMP, easing: FADE });

"use client";

import { useCurrentFrame } from "remotion";
import {
  BrushGrain,
  type BrushPoint,
  brushFilterId,
  brushReach,
  brushRibbon,
} from "@/components/remocn/brush";
import { DEFAULT_STEP, hashRange, steppedRamp } from "@/lib/remocn/stop-motion";

const SAMPLES_PER_LAP = 48;
const NOISE = 0.035;
const CENTRE = 0.02;

export type ScribbleCircleGeometry = {
  width: number;
  height: number;
  strokeWidth: number;
  laps?: number;
  pressure?: number;
  release?: number;
  grain?: number;
  seed?: string;
  points?: number;
  progress?: number;
};

export function scribbleCircleCentre(
  width: number,
  height: number,
  seed = "scribble",
): BrushPoint {
  return {
    x: width / 2 + hashRange(`${seed}:cx`, -CENTRE, CENTRE) * width,
    y: height / 2 + hashRange(`${seed}:cy`, -CENTRE, CENTRE) * height,
  };
}

export function scribbleCirclePoints(args: {
  width: number;
  height: number;
  laps?: number;
  seed?: string;
  points?: number;
}): BrushPoint[] {
  const laps = args.laps ?? 1.15;
  const seed = args.seed ?? "scribble";
  const points = args.points ?? SAMPLES_PER_LAP;

  const count = Math.max(2, Math.ceil(laps * points));
  const rx = args.width / 2;
  const ry = args.height / 2;
  const { x: cx, y: cy } = scribbleCircleCentre(args.width, args.height, seed);

  return Array.from({ length: count }, (_, i) => {
    const angle = laps * Math.PI * 2 * (i / (count - 1));
    const scale = 1 + hashRange(`${seed}:r${i}`, -NOISE, NOISE);
    return {
      x: cx + rx * scale * Math.cos(angle),
      y: cy + ry * scale * Math.sin(angle),
    };
  });
}

export function scribbleCirclePath(args: ScribbleCircleGeometry): {
  d: string;
  viewBox: string;
  marginX: number;
  marginY: number;
} {
  const grain = args.grain ?? 1;
  const reach = brushReach(args.strokeWidth, grain);
  const marginX = reach + (args.width / 2) * NOISE + args.width * CENTRE;
  const marginY = reach + (args.height / 2) * NOISE + args.height * CENTRE;

  return {
    d: brushRibbon(scribbleCirclePoints(args), {
      strokeWidth: args.strokeWidth,
      pressure: args.pressure,
      release: args.release,
      progress: args.progress,
    }),
    viewBox: `${-marginX} ${-marginY} ${args.width + marginX * 2} ${args.height + marginY * 2}`,
    marginX,
    marginY,
  };
}

export function scribbleCircleProgress(
  frame: number,
  options?: { delay?: number; durationSteps?: number; step?: number },
): number {
  const delay = options?.delay ?? 0;
  const durationSteps = options?.durationSteps ?? 10;
  const step = options?.step ?? DEFAULT_STEP;
  return steppedRamp(frame, delay, delay + durationSteps * step, { step });
}

export interface ScribbleCircleProps {
  width: number;
  height: number;
  color?: string;
  strokeWidth?: number;
  pressure?: number;
  release?: number;
  grain?: number;
  delay?: number;
  durationSteps?: number;
  laps?: number;
  seed?: string;
  step?: number;
}

export function ScribbleCircle({
  width,
  height,
  color = "#6f7f35",
  strokeWidth = 14,
  pressure = 0.2,
  release = 1,
  grain = 1,
  delay = 0,
  durationSteps = 10,
  laps = 1.15,
  seed = "scribble",
  step = DEFAULT_STEP,
}: ScribbleCircleProps) {
  const frame = useCurrentFrame();
  const progress = scribbleCircleProgress(frame, {
    delay,
    durationSteps,
    step,
  });
  const { d, viewBox, marginX, marginY } = scribbleCirclePath({
    width,
    height,
    strokeWidth,
    laps,
    pressure,
    release,
    grain,
    seed,
    progress,
  });

  return (
    <div
      style={{
        position: "relative",
        width,
        height,
        opacity: progress > 0 ? 1 : 0,
      }}
    >
      <svg
        width={width + marginX * 2}
        height={height + marginY * 2}
        viewBox={viewBox}
        style={{
          position: "absolute",
          left: -marginX,
          top: -marginY,
          display: "block",
          overflow: "visible",
        }}
      >
        <title>Scribbled circle</title>
        <BrushGrain seed={seed} strokeWidth={strokeWidth} grain={grain} />
        <path
          d={d}
          fill={color}
          opacity={0.85}
          filter={
            grain > 0
              ? `url(#${brushFilterId(seed, strokeWidth, grain)})`
              : undefined
          }
        />
      </svg>
    </div>
  );
}

"use client";

import type React from "react";
import { AbsoluteFill, useVideoConfig } from "remotion";
import {
  type CanvasFilterProps,
  makeCanvasFilter,
  makeFilterShader,
} from "@/lib/remocn/canvas-presentation";

export type SecurityCamProps = {
  compression?: number;
  blockSize?: number;
  noise?: number;
  intensity?: number;
};

const DEFAULTS = {
  compression: 0.7,
  blockSize: 10,
  noise: 0.6,
  intensity: 1,
};

type NormalizedProps = {
  compression: number;
  cellX: number;
  cellY: number;
  noise: number;
  intensity: number;
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_frame;
uniform vec2 u_cell;
uniform float u_compression;
uniform float u_noise;
uniform float u_intensity;

in vec2 v_uv;
out vec4 outColor;

const float PI = 3.141592653589793;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453123);
}

float lumaOf(vec3 c) {
  return dot(c, vec3(0.299, 0.587, 0.114));
}

vec2 chromaOf(vec3 c) {
  return vec2(c.b - lumaOf(c), c.r - lumaOf(c));
}

vec3 fromLumaChroma(float y, vec2 cbcr) {
  return vec3(y + cbcr.y, y - 0.194 * cbcr.x - 0.509 * cbcr.y, y + cbcr.x);
}

vec3 blockMean(vec2 origin, vec2 cell) {
  vec3 total = vec3(0.0);
  for (int y = 0; y < 2; y++) {
    for (int x = 0; x < 2; x++) {
      vec2 at = origin + (vec2(float(x), float(y)) + 0.5) * cell * 0.5;
      total += texture(u_scene, at).rgb;
    }
  }
  return total * 0.25;
}

void main() {
  vec4 src = texture(u_scene, v_uv);
  float amount = clamp(u_intensity, 0.0, 1.0);

  if (!(amount > 0.001)) {
    outColor = src;
    return;
  }

  vec2 cell = max(u_cell, vec2(0.0008));
  vec2 wide = cell * 2.0;

  vec3 lumaBlock = blockMean(floor(v_uv / cell) * cell, cell);
  vec3 chromaBlock = blockMean(floor(v_uv / wide) * wide, wide);

  float squeeze = clamp(u_compression, 0.0, 1.0) * amount;

  float y = mix(lumaOf(src.rgb), lumaOf(lumaBlock), squeeze * 0.8);
  float levels = mix(255.0, 20.0, squeeze);
  y = floor(y * levels + 0.5) / levels;

  vec2 cbcr = mix(chromaOf(src.rgb), chromaOf(chromaBlock), squeeze);
  cbcr *= mix(1.0, 0.62, amount);

  vec3 color = fromLumaChroma(y, cbcr);

  float pump = 1.0 + 0.03 * sin(u_frame * PI / 45.0) * amount;
  color = clamp((color * pump - 0.05 * amount) / (1.0 - 0.14 * amount), 0.0, 1.0);

  float clock = mod(u_frame, 64.0);
  float shadow = 1.0 - smoothstep(0.0, 0.55, y);
  float grain =
    hash(v_uv + vec2(clock * 0.017, clock * 0.029)) - 0.5;
  color += grain * 0.16 * u_noise * amount * (0.25 + shadow);

  outColor = vec4(clamp(color, 0.0, 1.0), src.a);
}`;

const shader = makeFilterShader<NormalizedProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const { compression, cellX, cellY, noise, intensity } = passedProps;
    gl.uniform1f(uniform("u_compression"), compression);
    gl.uniform2f(uniform("u_cell"), cellX, cellY);
    gl.uniform1f(uniform("u_noise"), noise);
    gl.uniform1f(uniform("u_intensity"), intensity);
  },
);

const SecurityCamFallback: React.FC<NormalizedProps & CanvasFilterProps> = ({
  children,
  intensity,
}) => (
  <AbsoluteFill>
    <AbsoluteFill
      style={{
        filter: `saturate(${1 - 0.38 * intensity}) contrast(${1 + 0.22 * intensity}) brightness(${1 - 0.05 * intensity})`,
      }}
    >
      {children}
    </AbsoluteFill>
    <AbsoluteFill
      style={{
        background:
          "radial-gradient(ellipse 82% 80% at 50% 50%, transparent 50%, rgba(0, 0, 0, 0.55) 100%)",
        opacity: intensity,
      }}
    />
  </AbsoluteFill>
);

const SecurityCamCanvas = makeCanvasFilter<NormalizedProps>({
  shader,
  fallback: SecurityCamFallback,
});

export const SecurityCam: React.FC<SecurityCamProps & CanvasFilterProps> = ({
  compression = DEFAULTS.compression,
  blockSize = DEFAULTS.blockSize,
  noise = DEFAULTS.noise,
  intensity = DEFAULTS.intensity,
  children,
}) => {
  const { width, height } = useVideoConfig();

  return (
    <SecurityCamCanvas
      compression={compression}
      cellX={Math.max(blockSize, 1) / width}
      cellY={Math.max(blockSize, 1) / height}
      noise={noise}
      intensity={intensity}
    >
      {children}
    </SecurityCamCanvas>
  );
};

"use client";

import { useEffect, useRef, useState } from "react";
import {
  continueRender,
  delayRender,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

// A field of refracted light — caustics. The web of bright filaments light
// makes when it passes through a surface and lands on the floor beneath.
// Written for the remocn registry as a custom WebGL shader (not a
// paper-design wrapper): frame-driven, deterministic, no wall-clock time.
//
// The filaments are slightly denser and brighter toward the bottom of the
// frame — the light lands on the base — which makes it a natural carrier for
// foundation stories. `accent` / `accentAmount` tint the filaments themselves
// (not the floor), so an undertone can arrive mid-video by animating
// `accentAmount` from the master timeline and stay in the light afterwards.

export interface ShaderCausticsProps {
  /** [floor color, filament light color]. */
  colors?: [string, string];
  /** Tint mixed into the bright filaments. */
  accent?: string;
  /** 0..1 — how much of the accent the filaments take. */
  accentAmount?: number;
  /** Spatial frequency of the light web. */
  scale?: number;
  /** Overall brightness of the filaments. */
  intensity?: number;
  /** Global time multiplier. */
  speed?: number;
  className?: string;
}

const VERT = `
attribute vec2 a_pos;
void main() {
  gl_Position = vec4(a_pos, 0.0, 1.0);
}
`;

const FRAG = `
precision highp float;

uniform vec2 u_res;
uniform float u_time;
uniform float u_scale;
uniform float u_intensity;
uniform vec3 u_floor;
uniform vec3 u_light;
uniform vec3 u_accent;
uniform float u_accentAmt;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float aspect = u_res.x / u_res.y;
  vec2 p = vec2(uv.x * aspect, uv.y) * u_scale;

  // Iterative trigonometric warp: each pass bends the sample point by the
  // previous pass, and the reciprocal distance to the warped axes
  // accumulates into the caustic web.
  float t = u_time * 0.35;
  vec2 i = p;
  float c = 0.0;
  for (int n = 0; n < 4; n++) {
    float phase = t * (1.0 - 3.2 / float(n + 2));
    i = p + vec2(
      cos(phase - i.x) + sin(phase + i.y),
      sin(phase - i.y) + cos(phase + i.x)
    );
    c += 1.0 / length(vec2(
      p.x / (sin(i.x + phase) * 90.0),
      p.y / (cos(i.y + phase) * 90.0)
    ));
  }
  c /= 4.0;
  c = 1.24 - pow(abs(c), 1.35);
  // |c| collapses to zero along thin branching veins — that zero-crossing
  // set IS the caustic web. Light the veins with an exponential falloff
  // (sharp core + a soft halo) and leave everything else near-black.
  float web = exp(-abs(c) * 0.5) + 0.22 * exp(-abs(c) * 0.12);
  web = web / (1.0 + 0.6 * web);

  // The light lands on the base: filaments read stronger low in the frame.
  float ground = mix(1.25, 0.55, uv.y);
  web *= ground * u_intensity;

  // Vignette keeps the corners quiet so type always wins.
  vec2 v = uv - 0.5;
  float vig = 1.0 - dot(v, v) * 1.1;
  web *= clamp(vig, 0.0, 1.0);

  vec3 filament = mix(u_light, u_accent, clamp(u_accentAmt, 0.0, 1.0));
  vec3 col = u_floor + filament * web;

  // A whisper of living grain, time-derived so it stays deterministic.
  col += (hash(gl_FragCoord.xy + floor(u_time * 9.0)) - 0.5) * 0.012;

  gl_FragColor = vec4(col, 1.0);
}
`;

const hexToRgb = (hex: string): [number, number, number] => {
  const h = hex.replace("#", "");
  const v =
    h.length === 3
      ? h
          .split("")
          .map((c) => c + c)
          .join("")
      : h;
  const n = parseInt(v, 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
};

type GlState = {
  gl: WebGLRenderingContext;
  uniforms: Record<string, WebGLUniformLocation | null>;
};

export function ShaderCaustics({
  colors = ["#0a0a0a", "#2e2e33"],
  accent = "#7F57FF",
  accentAmount = 0,
  scale = 5.2,
  intensity = 1,
  speed = 1,
  className,
}: ShaderCausticsProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const stateRef = useRef<GlState | null>(null);
  const [handle] = useState(() => delayRender("shader-caustics"));
  const continuedRef = useRef(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || stateRef.current) return;
    const gl = canvas.getContext("webgl", {
      antialias: false,
      preserveDrawingBuffer: true,
    });
    if (!gl) return;

    const compile = (type: number, src: string) => {
      const shader = gl.createShader(type);
      if (!shader) throw new Error("Failed to create WebGL shader");
      gl.shaderSource(shader, src);
      gl.compileShader(shader);
      return shader;
    };
    const program = gl.createProgram();
    if (!program) return;
    gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
    gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
    gl.linkProgram(program);
    // biome-ignore lint/correctness/useHookAtTopLevel: gl.useProgram is a WebGL method, not a React hook
    gl.useProgram(program);

    const buf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(
      gl.ARRAY_BUFFER,
      new Float32Array([-1, -1, 3, -1, -1, 3]),
      gl.STATIC_DRAW,
    );
    const loc = gl.getAttribLocation(program, "a_pos");
    gl.enableVertexAttribArray(loc);
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);

    const uniforms: GlState["uniforms"] = {};
    for (const name of [
      "u_res",
      "u_time",
      "u_scale",
      "u_intensity",
      "u_floor",
      "u_light",
      "u_accent",
      "u_accentAmt",
    ]) {
      uniforms[name] = gl.getUniformLocation(program, name);
    }
    stateRef.current = { gl, uniforms };
  }, []);

  useEffect(() => {
    const state = stateRef.current;
    const canvas = canvasRef.current;
    if (!state || !canvas) return;
    const { gl, uniforms } = state;

    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.uniform2f(uniforms.u_res, canvas.width, canvas.height);
    gl.uniform1f(uniforms.u_time, (frame / fps) * speed);
    gl.uniform1f(uniforms.u_scale, scale);
    gl.uniform1f(uniforms.u_intensity, intensity);
    gl.uniform3fv(uniforms.u_floor, hexToRgb(colors[0]));
    gl.uniform3fv(uniforms.u_light, hexToRgb(colors[1]));
    gl.uniform3fv(uniforms.u_accent, hexToRgb(accent));
    gl.uniform1f(uniforms.u_accentAmt, accentAmount);
    gl.drawArrays(gl.TRIANGLES, 0, 3);

    if (!continuedRef.current) {
      continuedRef.current = true;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    }
  }, [
    frame,
    fps,
    speed,
    scale,
    intensity,
    colors,
    accent,
    accentAmount,
    handle,
  ]);

  return (
    <div className={className} style={{ position: "absolute", inset: 0 }}>
      <canvas
        ref={canvasRef}
        width={width}
        height={height}
        style={{ width: "100%", height: "100%", display: "block" }}
      />
    </div>
  );
}

"use client";

import {
  ColorPanels,
