"use client";

import type { CSSProperties, ReactNode } from "react";
import {
  AbsoluteFill,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export type SlideSwapConfig = {
  sceneFrames: number;
  slideFrames: number;
  inDistance: number;
  inDamping: number;
  inStiffness: number;
  inMass: number;
  inFadeFrames: number;
  outFrames: number;
  outDistance: number;
  outPower: number;
};

export const SLIDE_SWAP_DEFAULTS: SlideSwapConfig = {
  sceneFrames: 70,
  slideFrames: 30,
  inDistance: 0.28,
  inDamping: 60,
  inStiffness: 300,
  inMass: 0.5,
  inFadeFrames: 24,
  outFrames: 22,
  outDistance: 0.1,
  outPower: 5,
};

export type SlideAxis = "x" | "y";

const translate = (axis: SlideAxis, v: number) =>
  axis === "x" ? `${v}px` : `0 ${v}px`;

export const slideInStyle = (
  e: number,
  size: number,
  fps: number,
  config?: Partial<SlideSwapConfig>,
  axis: SlideAxis = "x",
): CSSProperties => {
  const cfg = { ...SLIDE_SWAP_DEFAULTS, ...config };
  if (e >= cfg.slideFrames) return {};
  const p = spring({
    frame: Math.max(e, 0),
    fps,
    config: {
      damping: cfg.inDamping,
      stiffness: cfg.inStiffness,
      mass: cfg.inMass,
      overshootClamping: true,
    },
  });
  const tFade = Math.min(Math.max(e / cfg.inFadeFrames, 0), 1);
  return {
    translate: translate(axis, cfg.inDistance * size * (1 - p)),
    opacity: 1 - (1 - tFade) * (1 - tFade),
    willChange: "transform, opacity",
  };
};

export const slideOutStyle = (
  e: number,
  size: number,
  config?: Partial<SlideSwapConfig>,
  axis: SlideAxis = "x",
): CSSProperties => {
  const cfg = { ...SLIDE_SWAP_DEFAULTS, ...config };
  if (e <= 0) return {};
  const t = Math.min(e / cfg.outFrames, 1);
  return {
    translate: translate(axis, -cfg.outDistance * size * t ** cfg.outPower),
    opacity: 1 - t * t,
    willChange: "transform, opacity",
  };
};

export type SlideSwapSceneDef = {
  name?: string;
  durationInFrames?: number;
  content: ReactNode;
};

export type SlideSwapPhase = "slide" | "dwell" | "exit";

export type SlideSwapTimeline = {
  index: number;
  local: number;
  dwellFrames: number;
  phase: SlideSwapPhase;
};

export const slideSwapTimeline = (
  frame: number,
  scenes: SlideSwapSceneDef[],
  config?: Partial<SlideSwapConfig>,
  opts?: { loop?: boolean },
): SlideSwapTimeline => {
  const cfg = { ...SLIDE_SWAP_DEFAULTS, ...config };
  const lens = scenes.map((s) => s.durationInFrames ?? cfg.sceneFrames);
  const total = lens.reduce((a, b) => a + b, 0);
  let w = opts?.loop
    ? ((frame % total) + total) % total
    : Math.min(frame, total - 1);
  let index = 0;
  while (index < scenes.length - 1 && w >= lens[index]) {
    w -= lens[index];
    index += 1;
  }
  const local = Math.min(w, lens[index] - 1);
  const dwellFrames = lens[index];
  const exits = index < scenes.length - 1 || Boolean(opts?.loop);
  const enters = index > 0 || Boolean(opts?.loop);
  const phase: SlideSwapPhase =
    exits && local >= dwellFrames - cfg.outFrames
      ? "exit"
      : enters && local + 1 < cfg.slideFrames
        ? "slide"
        : "dwell";
  return { index, local, dwellFrames, phase };
};

export interface SlideSwapScenesProps {
  scenes: SlideSwapSceneDef[];
  bg?: string;
  axis?: SlideAxis;
  config?: Partial<SlideSwapConfig>;
  loop?: boolean;
  style?: CSSProperties;
}

export function SlideSwapScenes({
  scenes,
  bg,
  axis = "x",
  config,
  loop = false,
  style,
}: SlideSwapScenesProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const cfg = { ...SLIDE_SWAP_DEFAULTS, ...config };
  const size = axis === "x" ? width : height;

  const { index, local, dwellFrames, phase } = slideSwapTimeline(
    frame,
    scenes,
    cfg,
    { loop },
  );
  const cur = scenes[index];
  const enters = index > 0 || loop;

  const sceneStyle =
    phase === "exit"
      ? slideOutStyle(local - (dwellFrames - cfg.outFrames), size, cfg, axis)
      : enters
        ? slideInStyle(local + 1, size, fps, cfg, axis)
        : undefined;

  return (
    <AbsoluteFill style={{ background: bg, ...style }}>
      <AbsoluteFill style={sceneStyle}>{cur.content}</AbsoluteFill>
    </AbsoluteFill>
  );
}

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";
import { ShaderSmokeRing } from "@/components/remocn/shader-smoke-ring";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

const DEFAULT_COLORS = ["#8f88ae"];

export type SmokeDissolveProps = {
  colorBack?: string;
  colors?: string[];
  speed?: number;
};

const SmokeDissolvePresentation: React.FC<
  TransitionPresentationComponentProps<SmokeDissolveProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const {
    colorBack = "#141318",
    colors = DEFAULT_COLORS,
    speed = 1,
  } = passedProps;
  const entering = presentationDirection === "entering";
  const p = presentationProgress;

  const radius = interpolate(p, [0, 1], [0, 1], clampOpts);
  const scale = interpolate(p, [0, 1], [1, 2], clampOpts);
  const thickness = interpolate(p, [0, 1], [1, 1.5], clampOpts);

  const childStyle: React.CSSProperties = entering
    ? {
        opacity: interpolate(p, [0.55, 0.68], [0, 1], clampOpts),
        scale: `${interpolate(p, [0.55, 1], [0.3, 1], {
          ...clampOpts,
          easing: Easing.out(Easing.cubic),
        })}`,
        filter: `blur(${interpolate(p, [0.55, 0.75], [10, 0], clampOpts)}px)`,
      }
    : { opacity: interpolate(p, [0.06, 0.13], [1, 0], clampOpts) };

  return (
    <AbsoluteFill>
      {entering ? (
        <AbsoluteFill style={{ pointerEvents: "none" }}>
          <ShaderSmokeRing
            speed={speed}
            colorBack={colorBack}
            colors={colors}
            radius={radius}
            scale={scale}
            thickness={thickness}
          />
        </AbsoluteFill>
      ) : null}
      <AbsoluteFill style={childStyle}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

export function smokeDissolve(
  props: SmokeDissolveProps = {},
): TransitionPresentation<SmokeDissolveProps> {
  return {
    component: SmokeDissolvePresentation,
    props,
  };
}

"use client";

import type { CSSProperties, ReactNode } from "react";
import { createContext, useContext } from "react";
import {
  AbsoluteFill,
  interpolate,
  interpolateColors,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { CLAMP, FADE, stagger } from "@/lib/remocn/scene-motion";

export type SpringSettleConfig = {
  sceneFrames: number;
  gapFrames: number;
  enterScale: number;
  enterFadeFrames: number;
  enterStagger: number;
  enterStaggerPower: number;
  enterStaggerJitter: number;
  springDamping: number;
  springStiffness: number;
  springMass: number;
  exitFrames: number;
  exitScale: number;
  exitPower: number;
  bgFadeFrames: number;
};

export const SPRING_SETTLE_DEFAULTS: SpringSettleConfig = {
  sceneFrames: 70,
  gapFrames: 1,
  enterScale: 1.24,
  enterFadeFrames: 5,
  enterStagger: 3,
  enterStaggerPower: 0.8,
  enterStaggerJitter: 1,
  springDamping: 30,
  springStiffness: 320,
  springMass: 1,
  exitFrames: 6,
  exitScale: 0.84,
  exitPower: 5,
  bgFadeFrames: 4,
};

export type SpringSettleSceneDef = {
  name?: string;
  bg?: string;
  durationInFrames?: number;
  content: ReactNode;
};

export type SpringSettlePhase = "enter" | "dwell" | "exit" | "gap";

export type SpringSettleTimeline = {
  index: number;
  local: number;
  dwellFrames: number;
};

type SceneClock = {
  local: number;
  cfg: SpringSettleConfig;
  fps: number;
};

const SceneCtx = createContext<SceneClock | null>(null);

const resolveConfig = (
  config?: Partial<SpringSettleConfig>,
): SpringSettleConfig => ({ ...SPRING_SETTLE_DEFAULTS, ...config });

const dwellOf = (scene: SpringSettleSceneDef, cfg: SpringSettleConfig) =>
  scene.durationInFrames ?? cfg.sceneFrames;

export const springSettleTimeline = (
  frame: number,
  scenes: SpringSettleSceneDef[],
  config?: Partial<SpringSettleConfig>,
  opts?: { loop?: boolean },
): SpringSettleTimeline => {
  const cfg = resolveConfig(config);
  const lens = scenes.map((s) => dwellOf(s, cfg) + cfg.gapFrames);
  const total = lens.reduce((a, b) => a + b, 0);
  let w = opts?.loop ? ((frame % total) + total) % total : frame;
  let index = 0;
  while (index < scenes.length - 1 && w >= lens[index]) {
    w -= lens[index];
    index += 1;
  }
  const local = Math.min(w, lens[index] - 1);
  return { index, local, dwellFrames: dwellOf(scenes[index], cfg) };
};

export const springSettlePhase = (
  timeline: SpringSettleTimeline,
  fps: number,
  config?: Partial<SpringSettleConfig>,
): SpringSettlePhase => {
  const cfg = resolveConfig(config);
  const { local, dwellFrames } = timeline;
  if (local >= dwellFrames) return "gap";
  if (local >= dwellFrames - cfg.exitFrames) return "exit";
  const settled =
    spring({
      frame: local,
      fps,
      config: {
        damping: cfg.springDamping,
        stiffness: cfg.springStiffness,
        mass: cfg.springMass,
      },
    }) > 0.985;
  return settled ? "dwell" : "enter";
};

export const springSettleExitStyle = (
  local: number,
  dwellFrames: number,
  config?: Partial<SpringSettleConfig>,
): CSSProperties => {
  const cfg = resolveConfig(config);
  const tExit = interpolate(
    local,
    [dwellFrames - cfg.exitFrames, dwellFrames],
    [0, 1],
    CLAMP,
  );
  if (tExit <= 0) return {};
  const eExit = tExit ** cfg.exitPower;
  return {
    scale: `${1 - (1 - cfg.exitScale) * eExit}`,
    opacity: 1 - eExit,
    willChange: "transform, opacity",
  };
};

export interface SpringSettleEnterProps {
  local: number;
  config?: Partial<SpringSettleConfig>;
  children: ReactNode;
}

export function SpringSettleEnter({
  local,
  config,
  children,
}: SpringSettleEnterProps) {
  const { fps } = useVideoConfig();
  return (
    <SceneCtx.Provider value={{ local, cfg: resolveConfig(config), fps }}>
      {children}
    </SceneCtx.Provider>
  );
}

export interface SpringSettleItemProps {
  index?: number;
  style?: CSSProperties;
  children: ReactNode;
}

export function SpringSettleItem({
  index = 0,
  style,
  children,
}: SpringSettleItemProps) {
  const clock = useContext(SceneCtx);
  if (!clock) {
    return <div style={style}>{children}</div>;
  }
  const { local, cfg, fps } = clock;
  const tEnter =
    local -
    stagger(
      index,
      cfg.enterStagger,
      cfg.enterStaggerPower,
      cfg.enterStaggerJitter,
    );
  const enterP = spring({
    frame: tEnter,
    fps,
    config: {
      damping: cfg.springDamping,
      stiffness: cfg.springStiffness,
      mass: cfg.springMass,
    },
  });
  const scaleEnter = interpolate(enterP, [0, 1], [cfg.enterScale, 1]);
  const opacityEnter = interpolate(tEnter, [0, cfg.enterFadeFrames], [0, 1], {
    ...CLAMP,
    easing: FADE,
  });
  return (
    <div
      style={{
        ...style,
        scale: `${scaleEnter}`,
        opacity: opacityEnter,
        willChange: "transform, opacity",
      }}
    >
      {children}
    </div>
  );
}

const wrapSigned = (d: number, total: number) =>
  (((d % total) + total * 1.5) % total) - total / 2;

export interface SpringSettleScenesProps {
  scenes: SpringSettleSceneDef[];
  config?: Partial<SpringSettleConfig>;
  loop?: boolean;
  style?: CSSProperties;
}

export function SpringSettleScenes({
  scenes,
  config,
  loop = false,
  style,
}: SpringSettleScenesProps) {
  const frame = useCurrentFrame();
  const cfg = resolveConfig(config);

  const lens = scenes.map((s) => dwellOf(s, cfg) + cfg.gapFrames);
  const total = lens.reduce((a, b) => a + b, 0);
  const { index, local, dwellFrames } = springSettleTimeline(
    frame,
    scenes,
    cfg,
    { loop },
  );

  const n = scenes.length;
  const cur = scenes[index];
  const prev = loop ? scenes[(index - 1 + n) % n] : scenes[index - 1];
  const next = loop ? scenes[(index + 1) % n] : scenes[index + 1];

  const w = loop ? ((frame % total) + total) % total : frame;
  const slotStart = w - local;
  const half = Math.max(cfg.bgFadeFrames, 0.001) / 2;
  let bg = cur.bg;
  if (prev?.bg && cur.bg) {
    let d = w - (slotStart - cfg.gapFrames / 2);
    if (loop) d = wrapSigned(d, total);
    if (Math.abs(d) <= half) {
      bg = interpolateColors(d, [-half, half], [prev.bg, cur.bg]);
    }
  }
  if (next?.bg && cur.bg && bg === cur.bg) {
    let d = w - (slotStart + dwellFrames + cfg.gapFrames / 2);
    if (loop) d = wrapSigned(d, total);
    if (Math.abs(d) <= half) {
      bg = interpolateColors(d, [-half, half], [cur.bg, next.bg]);
    }
  }

  return (
    <AbsoluteFill style={{ background: bg, ...style }}>
      {local < dwellFrames ? (
        <AbsoluteFill style={springSettleExitStyle(local, dwellFrames, cfg)}>
          <SpringSettleEnter local={local} config={cfg}>
            {cur.content}
          </SpringSettleEnter>
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
}

import { spring } from "remotion";

export const DEFAULT_STEP = 3;

export const qf = (frame: number, step = DEFAULT_STEP): number =>
  Math.floor(frame / step) * step;

export const qstep = (frame: number, step = DEFAULT_STEP): number =>
  Math.floor(frame / step);

export const hash01 = (seed: string): number => {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  h = Math.imul(h ^ (h >>> 13), 2246822519);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
};

export const hashRange = (seed: string, lo: number, hi: number): number =>
  lo + hash01(seed) * (hi - lo);

export type Jitter = { x: number; y: number; rot: number };

export const paperJitter = (
  frame: number,
  seed: string,
  options?: { amp?: number; rotAmp?: number; step?: number },
): Jitter => {
  const amp = options?.amp ?? 1.4;
  const rotAmp = options?.rotAmp ?? 0.35;
  const s = qstep(frame, options?.step ?? DEFAULT_STEP);
  return {
    x: hashRange(`${seed}:x:${s}`, -amp, amp),
    y: hashRange(`${seed}:y:${s}`, -amp, amp),
    rot: hashRange(`${seed}:r:${s}`, -rotAmp, rotAmp),
  };
};

export const steppedSpring = (args: {
  frame: number;
  fps: number;
  delay?: number;
  step?: number;
  config?: { damping?: number; stiffness?: number; mass?: number };
}): number =>
  spring({
    frame: qf(
      Math.max(0, args.frame - (args.delay ?? 0)),
      args.step ?? DEFAULT_STEP,
    ),
    fps: args.fps,
    config: args.config,
  });

export const steppedRamp = (
  frame: number,
  from: number,
  to: number,
  options?: { ease?: (t: number) => number; step?: number },
): number => {
  const f = qf(frame, options?.step ?? DEFAULT_STEP);
  if (f <= from) return 0;
  if (f >= to) return 1;
  const ease = options?.ease ?? ((t: number) => t);
  return ease((f - from) / (to - from));
};

"use client";

import type React from "react";
import { AbsoluteFill, random, useCurrentFrame } from "remotion";
import {
  type CanvasFilterProps,
  makeCanvasFilter,
  makeFilterShader,
} from "@/lib/remocn/canvas-presentation";

export type SustainedGlitchProps = {
  intensity?: number;
  frequency?: number;
  slices?: number;
  seed?: number;
};

const DEFAULTS = {
  intensity: 1,
  frequency: 1,
  slices: 24,
  seed: 1,
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_frame;
uniform float u_intensity;
uniform float u_frequency;
uniform float u_slices;
uniform float u_seed;

in vec2 v_uv;
out vec4 outColor;

const float BLOCK_COLUMNS = 16.0;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

vec4 sampleSplit(vec2 uv, float split) {
  vec4 center = texture(u_scene, uv);
  float r = texture(u_scene, fract(vec2(uv.x + split, uv.y))).r;
  float b = texture(u_scene, fract(vec2(uv.x - split, uv.y))).b;
  return vec4(r, center.g, b, center.a);
}

void main() {
  float slotLength = max(30.0 / max(u_frequency, 0.1), 4.0);
  float slot = floor(u_frame / slotLength);
  float local = u_frame - slot * slotLength;

  float burstLength = 2.0 + floor(hash(vec2(slot, u_seed + 2.0)) * 4.0);
  float start =
    floor(hash(vec2(slot, u_seed + 1.0)) * max(slotLength - burstLength, 1.0));
  float fires = step(0.25, hash(vec2(slot, u_seed + 3.0)));

  float age = local - start;
  float live = fires * step(0.0, age) * step(age, burstLength - 1.0);
  float energy =
    max(u_intensity, 0.0) * live * (1.0 - age / burstLength);

  if (energy <= 0.0) {
    outColor = texture(u_scene, v_uv);
    return;
  }

  float clock = mod(u_frame, 512.0) + u_seed;
  float row = floor(v_uv.y * max(u_slices, 2.0));
  float torn = step(0.45, hash(vec2(row, clock)));
  float amount = hash(vec2(row + 17.0, clock * 1.7 + 3.0)) - 0.5;
  float sliceShift = amount * 0.28 * energy * torn;

  vec2 block = vec2(floor(v_uv.x * BLOCK_COLUMNS), row);
  float corrupt = step(1.0 - 0.45 * min(energy, 1.0), hash(block + clock * 7.3));
  vec2 jump =
    vec2(
      hash(block + clock * 3.1 + 5.0) - 0.5,
      hash(block + clock * 9.7 + 11.0) - 0.5
    ) *
    vec2(0.62, 0.34) *
    corrupt;

  vec2 uv = fract(v_uv + vec2(sliceShift, 0.0) + jump);
  float split = 0.02 * energy * (0.35 + abs(amount));

  vec4 color = sampleSplit(uv, split);
  color.rgb +=
    vec3(0.05, 0.015, 0.09) *
    energy *
    torn *
    hash(vec2(row, clock + 41.0)) *
    color.a;

  outColor = vec4(clamp(color.rgb, 0.0, 1.0), color.a);
}`;

const shader = makeFilterShader<SustainedGlitchProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const {
      intensity = DEFAULTS.intensity,
      frequency = DEFAULTS.frequency,
      slices = DEFAULTS.slices,
      seed = DEFAULTS.seed,
    } = passedProps;
    gl.uniform1f(uniform("u_intensity"), intensity);
    gl.uniform1f(uniform("u_frequency"), frequency);
    gl.uniform1f(uniform("u_slices"), slices);
    gl.uniform1f(uniform("u_seed"), seed);
  },
);

function burstEnergy(
  frame: number,
  intensity: number,
  frequency: number,
  seed: number,
): number {
  const slotLength = Math.max(30 / Math.max(frequency, 0.1), 4);
  const slot = Math.floor(frame / slotLength);
  const local = frame - slot * slotLength;

  const burstLength = 2 + Math.floor(random(`glitch-len-${seed}-${slot}`) * 4);
  const start = Math.floor(
    random(`glitch-start-${seed}-${slot}`) *
      Math.max(slotLength - burstLength, 1),
  );
  if (random(`glitch-fire-${seed}-${slot}`) < 0.25) return 0;

  const age = local - start;
  if (age < 0 || age > burstLength - 1) return 0;
  return Math.max(intensity, 0) * (1 - age / burstLength);
}

const SustainedGlitchFallback: React.FC<
  SustainedGlitchProps & CanvasFilterProps
> = ({
  children,
  intensity = DEFAULTS.intensity,
  frequency = DEFAULTS.frequency,
  slices = DEFAULTS.slices,
  seed = DEFAULTS.seed,
}) => {
  const frame = useCurrentFrame();
  const energy = burstEnergy(frame, intensity, frequency, seed);

  if (energy <= 0) {
    return <AbsoluteFill>{children}</AbsoluteFill>;
  }

  const bands = Math.max(2, Math.min(6, Math.round(slices / 5)));
  const height = 100 / bands;

  return (
    <AbsoluteFill>
      {Array.from({ length: bands }, (_, band) => {
        const shift =
          (random(`glitch-shift-${seed}-${frame}-${band}`) - 0.5) * 46 * energy;
        const tint = band % 2 === 0 ? "rgb(255, 42, 90)" : "rgb(0, 224, 255)";
        return (
          <AbsoluteFill
            key={band}
            style={{
              clipPath: `inset(${band * height}% 0 ${100 - (band + 1) * height}% 0)`,
              translate: `${shift}px`,
            }}
          >
            {children}
            <AbsoluteFill
              style={{
                background: tint,
                mixBlendMode: "screen",
                opacity:
                  0.18 *
                  energy *
                  random(`glitch-tint-${seed}-${frame}-${band}`),
              }}
            />
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

export const SustainedGlitch = makeCanvasFilter<SustainedGlitchProps>({
  shader,
  fallback: SustainedGlitchFallback,
});

"use client";

import type {
  TransitionPresentation,
  TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type React from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";
import { ShaderSwirl } from "@/components/remocn/shader-swirl";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

const DEFAULT_COLORS = ["#1f1d29", "#413d56", "#8f88ae"];

export type SwirlDissolveProps = {
  colors?: string[];
  colorBack?: string;
  bandCount?: number;
  softness?: number;
  speed?: number;
};

const SwirlDissolvePresentation: React.FC<
  TransitionPresentationComponentProps<SwirlDissolveProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const {
    colors = DEFAULT_COLORS,
    colorBack = "#141318",
    bandCount = 10,
    softness = 0.35,
    speed = 1,
  } = passedProps;
  const entering = presentationDirection === "entering";
  const p = presentationProgress;

  const twist = interpolate(p, [0.1, 0.42, 0.64, 1], [1, 0, 0, 1], {
    ...clampOpts,
    easing: Easing.bezier(0.42, 0, 0.58, 1),
  });

  const childStyle: React.CSSProperties = entering
    ? {
        opacity: interpolate(p, [0.77, 0.87], [0, 1], clampOpts),
        scale: `${interpolate(p, [0.77, 1], [0.3, 1], {
          ...clampOpts,
          easing: Easing.out(Easing.cubic),
        })}`,
        filter: `blur(${interpolate(p, [0.77, 0.93], [10, 0], clampOpts)}px)`,
      }
    : { opacity: interpolate(p, [0.06, 0.13], [1, 0], clampOpts) };

  return (
    <AbsoluteFill>
      {entering ? (
        <AbsoluteFill style={{ pointerEvents: "none" }}>
          <ShaderSwirl
            speed={speed}
            twist={twist}
            colors={colors}
            colorBack={colorBack}
            bandCount={bandCount}
            softness={softness}
          />
        </AbsoluteFill>
      ) : null}
      <AbsoluteFill style={childStyle}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

export function swirlDissolve(
  props: SwirlDissolveProps = {},
): TransitionPresentation<SwirlDissolveProps> {
  return {
    component: SwirlDissolvePresentation,
    props,
  };
}

"use client";

import type React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import {
  type CanvasFilterProps,
  makeCanvasFilter,
  makeFilterShader,
} from "@/lib/remocn/canvas-presentation";

export type TvPowerOffProps = {
  durationInFrames?: number;
  delay?: number;
  gain?: number;
  afterglow?: number;
  phosphor?: string;
};

const DEFAULTS = {
  durationInFrames: 18,
  delay: 0,
  gain: 1,
  afterglow: 1,
  phosphor: "#d8ecff",
};

const COLLAPSE_END = 0.6;
const PINCH_END = 0.82;
const MIN_SQUASH = 0.0055;
const MIN_PINCH = 0.004;
const CONCENTRATION = 0.3;
const DECAY_CURVE = 2.6;
const BLACKOUT_IN = 0.06;

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform vec2 u_resolution;
uniform float u_aspect;
uniform float u_progress;
uniform float u_gain;
uniform float u_afterglow;
uniform vec3 u_phosphor;

in vec2 v_uv;
out vec4 outColor;

const int TAPS = 32;
const int COLUMN_TAPS = 8;
const float GOLDEN = 0.6180339887;
const float COLLAPSE_END = ${COLLAPSE_END.toFixed(4)};
const float PINCH_END = ${PINCH_END.toFixed(4)};
const float MIN_SQUASH = ${MIN_SQUASH.toFixed(5)};
const float MIN_PINCH = ${MIN_PINCH.toFixed(5)};
const float CONCENTRATION = ${CONCENTRATION.toFixed(4)};
const float DECAY_CURVE = ${DECAY_CURVE.toFixed(4)};
const float BLACKOUT_IN = ${BLACKOUT_IN.toFixed(4)};

void main() {
  float p = u_progress;

  if (p <= 0.0) {
    outColor = texture(u_scene, v_uv);
    return;
  }
  if (p >= 1.0) {
    outColor = vec4(0.0, 0.0, 0.0, 1.0);
    return;
  }

  float collapse = clamp(p / COLLAPSE_END, 0.0, 1.0);
  float pinch = clamp((p - COLLAPSE_END) / (PINCH_END - COLLAPSE_END), 0.0, 1.0);
  float decayed = clamp((p - PINCH_END) / (1.0 - PINCH_END), 0.0, 1.0);

  vec2 scale = vec2(pow(MIN_PINCH, pinch), pow(MIN_SQUASH, collapse));
  vec2 centered = (v_uv - 0.5) / scale + 0.5;
  vec2 span = 1.0 / (scale * u_resolution);

  vec3 sum = vec3(0.0);
  for (int i = 0; i < TAPS; i++) {
    float fi = float(i);
    vec2 at = centered + vec2(
      (fract(fi * GOLDEN + 0.5) - 0.5) * span.x,
      ((fi + 0.5) / float(TAPS) - 0.5) * span.y
    );
    vec2 inside = step(vec2(0.0), at) * step(at, vec2(1.0));
    sum += texture(u_scene, at).rgb * inside.x * inside.y;
  }

  float concentrate = pow(1.0 / (scale.x * scale.y), CONCENTRATION);
  vec3 light =
    (sum / float(TAPS)) * (1.0 + (concentrate - 1.0) * max(u_gain, 0.0));

  float glow = max(u_afterglow, 0.0);
  float bleed = smoothstep(0.2, 0.8, collapse) * (1.0 - pinch) * glow;

  if (bleed > 0.0) {
    vec3 column = vec3(0.0);
    float cx = clamp(centered.x, 0.0, 1.0);
    for (int i = 0; i < COLUMN_TAPS; i++) {
      column +=
        texture(u_scene, vec2(cx, (float(i) + 0.5) / float(COLUMN_TAPS))).rgb;
    }
    column /= float(COLUMN_TAPS);

    float dy = v_uv.y - 0.5;
    float reach = 0.02 + 0.03 * collapse;
    light +=
      column *
      mix(vec3(1.0), u_phosphor, 0.65) *
      exp(-(dy * dy) / (reach * reach)) *
      bleed *
      0.9;
  }

  if (pinch > 0.0) {
    vec2 d = (v_uv - 0.5) * vec2(u_aspect, 1.0);
    float radius = max(0.045 * glow, 0.0005);
    light +=
      u_phosphor *
      exp(-dot(d, d) / (radius * radius)) *
      smoothstep(0.0, 0.5, pinch) *
      1.15;
  }

  light *= pow(max(1.0 - decayed, 0.0001), DECAY_CURVE);

  float blackout = smoothstep(0.0, BLACKOUT_IN, p);
  outColor = vec4(
    clamp(light, 0.0, 1.0),
    mix(texture(u_scene, v_uv).a, 1.0, blackout)
  );
}`;

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

function toRgb(hex: string): [number, number, number] {
  const value = hex.replace("#", "");
  const full =
    value.length === 3
      ? value
          .split("")
          .map((c) => c + c)
          .join("")
      : value;
  const int = Number.parseInt(full, 16);
  if (Number.isNaN(int)) return [1, 1, 1];
  return [
    ((int >> 16) & 255) / 255,
    ((int >> 8) & 255) / 255,
    (int & 255) / 255,
  ];
}

function powerProgress(props: TvPowerOffProps, frame: number): number {
  const {
    durationInFrames = DEFAULTS.durationInFrames,
    delay = DEFAULTS.delay,
  } = props;
  return clamp((frame - delay) / Math.max(1, durationInFrames), 0, 1);
}

const shader = makeFilterShader<TvPowerOffProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, width, height, frame, passedProps }) => {
    const {
      gain = DEFAULTS.gain,
      afterglow = DEFAULTS.afterglow,
      phosphor = DEFAULTS.phosphor,
    } = passedProps;
    gl.uniform1f(uniform("u_progress"), powerProgress(passedProps, frame));
    gl.uniform2f(uniform("u_resolution"), width, height);
    gl.uniform1f(uniform("u_gain"), gain);
    gl.uniform1f(uniform("u_afterglow"), afterglow);
    gl.uniform3fv(uniform("u_phosphor"), toRgb(phosphor));
  },
);

const TvPowerOffFallback: React.FC<TvPowerOffProps & CanvasFilterProps> = (
  props,
) => {
  const frame = useCurrentFrame();
  const {
    children,
    gain = DEFAULTS.gain,
    afterglow = DEFAULTS.afterglow,
    phosphor = DEFAULTS.phosphor,
  } = props;

  const p = powerProgress(props, frame);
  const collapse = clamp(p / COLLAPSE_END, 0, 1);
  const pinch = clamp((p - COLLAPSE_END) / (PINCH_END - COLLAPSE_END), 0, 1);
  const decayed = clamp((p - PINCH_END) / (1 - PINCH_END), 0, 1);

  const squash = MIN_SQUASH ** collapse;
  const pinchX = MIN_PINCH ** pinch;
  const concentrate = (1 / (squash * pinchX)) ** CONCENTRATION;
  const fade = (1 - decayed) ** DECAY_CURVE;

  return (
    <AbsoluteFill>
      <AbsoluteFill
        style={{
          background: "#000000",
          opacity: clamp(p / BLACKOUT_IN, 0, 1),
        }}
      />
      <AbsoluteFill
        style={{
          scale: `${pinchX} ${squash}`,
          filter: `brightness(${1 + (concentrate - 1) * Math.max(gain, 0)})`,
          opacity: fade,
        }}
      >
        {children}
      </AbsoluteFill>
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at 50% 50%, ${phosphor} 0%, transparent 55%)`,
          opacity: clamp(pinch * afterglow, 0, 1) * fade,
        }}
      />
    </AbsoluteFill>
  );
};

export const TvPowerOff = makeCanvasFilter<TvPowerOffProps>({
  shader,
  fallback: TvPowerOffFallback,
});

"use client";

import type React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import {
  type CanvasFilterProps,
  makeCanvasFilter,
  makeFilterShader,
} from "@/lib/remocn/canvas-presentation";

export type UnderwaterRippleProps = {
  amplitude?: number;
  scale?: number;
  speed?: number;
  dispersion?: number;
};

const DEFAULTS = {
  amplitude: 7,
  scale: 1,
  speed: 2,
  dispersion: 1,
};

type NormalizedProps = {
  amplitude: number;
  scale: number;
  phase: number;
  dispersion: number;
};

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_aspect;
uniform float u_phase;
uniform float u_amplitude;
uniform float u_scale;
uniform float u_dispersion;

in vec2 v_uv;
out vec4 outColor;

vec2 fieldGradient(vec2 p, float phase) {
  float scale = max(u_scale, 0.05);
  vec2 k1 = vec2(1.0, 0.35);
  vec2 k2 = vec2(-0.42, 1.0);
  vec2 k3 = vec2(0.78, -0.63);
  float f1 = 6.1 * scale;
  float f2 = 8.7 * scale;
  float f3 = 12.3 * scale;

  vec2 g = vec2(0.0);
  g += cos(dot(p, k1) * f1 + phase) * f1 * k1;
  g += cos(dot(p, k2) * f2 - phase * 2.0) * f2 * k2;
  g += cos(dot(p, k3) * f3 + phase * 3.0) * f3 * k3;

  return g / (3.0 * f2);
}

void main() {
  vec2 p = vec2(v_uv.x * u_aspect, v_uv.y);
  vec2 grad = fieldGradient(p, u_phase);

  vec2 offset = grad * u_amplitude;
  float strength = length(grad);
  vec2 direction = strength > 0.0001 ? grad / strength : vec2(0.0);
  float spread = u_dispersion * u_amplitude * 0.3 * min(strength, 2.0);

  vec2 base = v_uv + vec2(offset.x / u_aspect, offset.y);
  vec2 lead = vec2(direction.x / u_aspect, direction.y) * spread;

  vec4 center = texture(u_scene, base);
  float r = texture(u_scene, base + lead).r;
  float b = texture(u_scene, base - lead).b;

  outColor = vec4(r, center.g, b, center.a);
}`;

const shader = makeFilterShader<NormalizedProps>(
  FRAGMENT_SHADER,
  ({ gl, uniform, passedProps }) => {
    const { amplitude, scale, phase, dispersion } = passedProps;
    gl.uniform1f(uniform("u_amplitude"), amplitude);
    gl.uniform1f(uniform("u_scale"), scale);
    gl.uniform1f(uniform("u_phase"), phase);
    gl.uniform1f(uniform("u_dispersion"), dispersion);
  },
);

const UnderwaterRippleFallback: React.FC<
  NormalizedProps & CanvasFilterProps
> = ({ children }) => <AbsoluteFill>{children}</AbsoluteFill>;

const UnderwaterRippleCanvas = makeCanvasFilter<NormalizedProps>({
  shader,
  fallback: UnderwaterRippleFallback,
});

export const UnderwaterRipple: React.FC<
  UnderwaterRippleProps & CanvasFilterProps
> = ({
  amplitude = DEFAULTS.amplitude,
  scale = DEFAULTS.scale,
  speed = DEFAULTS.speed,
  dispersion = DEFAULTS.dispersion,
  children,
}) => {
  const frame = useCurrentFrame();
  const { height, durationInFrames } = useVideoConfig();
  const cycle = Math.max(durationInFrames, 1);

  return (
    <UnderwaterRippleCanvas
      amplitude={amplitude / height}
      scale={scale}
      phase={(frame / cycle) * speed * Math.PI * 2}
      dispersion={dispersion}
    >
      {children}
    </UnderwaterRippleCanvas>
  );
};

